module.exports = [{"id":"thread-Java中实现多线程有几种方法","module":"thread","title":"Java中实现多线程有几种方法","level":"core","summary":"面试常说四种：继承 Thread、实现 Runnable、实现 Callable、用…","blocks":[{"type":"p","inlines":[{"t":"text","v":"面试常说四种：继承 Thread、实现 Runnable、实现 Callable、用线程池。前三种是怎么定义任务，线程池是怎么跑任务。本质都是 Thread 去执行一个任务。"}]},{"type":"p","inlines":[{"t":"text","v":"继承 Thread：重写 "},{"t":"code","v":"run()"},{"t":"text","v":"，"},{"t":"code","v":"new MyThread().start()"},{"t":"text","v":"。简单，但 Java 单继承，业务类再继承别的就不行。一般不推荐。"}]},{"type":"p","inlines":[{"t":"text","v":"实现 Runnable：重写 "},{"t":"code","v":"run()"},{"t":"text","v":"，"},{"t":"code","v":"new Thread(runnable).start()"},{"t":"text","v":"。任务和线程分开，一个 Runnable 还能丢给多个线程，也能进线程池。没有返回值，不能往外抛受检异常。"}]},{"type":"p","inlines":[{"t":"text","v":"实现 Callable："},{"t":"code","v":"call()"},{"t":"text","v":" 有返回值，还能抛异常。要配 FutureTask："},{"t":"code","v":"FutureTask<V> ft = new FutureTask<>(callable); new Thread(ft).start(); ft.get()"},{"t":"text","v":" 取结果。"},{"t":"code","v":"get()"},{"t":"text","v":" 会阻塞到算完。"}]},{"type":"p","inlines":[{"t":"text","v":"线程池："},{"t":"code","v":"ExecutorService"},{"t":"text","v":" 提交 Runnable 或 Callable，由池里的线程来跑，不要自己 "},{"t":"code","v":"new Thread"},{"t":"text","v":"。生产上这是正经用法，能复用线程、控数量、排队、拒绝策略。"}]},{"type":"p","inlines":[{"t":"text","v":"另外还有 "},{"t":"code","v":"CompletableFuture"},{"t":"text","v":"、定时任务这些，都是包在线程池上面的写法，不算第五种创建线程的底层方式。"}]}]},{"id":"thread-Java中实现多线程有几种方法-start-和-run-有什么区别","module":"thread","title":"start 和 run 有什么区别","level":"extra","summary":"start() 才是真正起一个新线程，之后 JVM 去调 run()。直接调 run…","blocks":[{"type":"p","inlines":[{"t":"code","v":"start()"},{"t":"text","v":" 才是真正起一个新线程，之后 JVM 去调 "},{"t":"code","v":"run()"},{"t":"text","v":"。直接调 "},{"t":"code","v":"run()"},{"t":"text","v":" 就是普通方法，还在当前线程里执行，不会并行。面试里说「实现多线程」一定是 "},{"t":"code","v":"start()"},{"t":"text","v":" 或交给线程池。"}]}],"parentId":"thread-Java中实现多线程有几种方法"},{"id":"thread-Java中实现多线程有几种方法-Runnable-和-Callable-怎么选","module":"thread","title":"Runnable 和 Callable 怎么选","level":"extra","summary":"不关心结果用 Runnable。要返回值或要往外抛异常用 Callable，用 Fu…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不关心结果用 Runnable。要返回值或要往外抛异常用 Callable，用 "},{"t":"code","v":"Future"},{"t":"text","v":" / "},{"t":"code","v":"FutureTask"},{"t":"text","v":" 接。线程池 "},{"t":"code","v":"submit(Callable)"},{"t":"text","v":" 也会拿到 Future。"}]}],"parentId":"thread-Java中实现多线程有几种方法"},{"id":"thread-Java中实现多线程有几种方法-为什么生产不用每次-new-Thread","module":"thread","title":"为什么生产不用每次 new Thread","level":"extra","summary":"无线程复用，创建和销毁贵；数量不好控，流量一高容易把机器打满；没有统一的排队和拒绝。…","blocks":[{"type":"p","inlines":[{"t":"text","v":"无线程复用，创建和销毁贵；数量不好控，流量一高容易把机器打满；没有统一的排队和拒绝。线程池把这些收口了。自己 "},{"t":"code","v":"new Thread"},{"t":"text","v":" 只适合演示或明确的一次性后台线程。"}]}],"parentId":"thread-Java中实现多线程有几种方法"},{"id":"thread-如何停止一个正在运行的线程","module":"thread","title":"如何停止一个正在运行的线程","level":"core","summary":"三种说法面试常考，真正能用的是前两种协作式，第三种废弃。","blocks":[{"type":"p","inlines":[{"t":"text","v":"三种说法面试常考，真正能用的是前两种协作式，第三种废弃。"}]},{"type":"p","inlines":[{"t":"text","v":"用退出标志：设一个 "},{"t":"code","v":"volatile boolean stop"},{"t":"text","v":"，"},{"t":"code","v":"run"},{"t":"text","v":" 里 "},{"t":"code","v":"while (!stop)"},{"t":"text","v":"，外面改成 "},{"t":"code","v":"true"},{"t":"text","v":"，线程跑完本轮循环就正常退出。适合自己写的循环任务。"}]},{"type":"p","inlines":[{"t":"text","v":"用 "},{"t":"code","v":"interrupt()"},{"t":"text","v":"：调 "},{"t":"code","v":"thread.interrupt()"},{"t":"text","v":"。卡在 "},{"t":"code","v":"sleep"},{"t":"text","v":"、"},{"t":"code","v":"wait"},{"t":"text","v":"、"},{"t":"code","v":"join"},{"t":"text","v":" 时会抛 "},{"t":"code","v":"InterruptedException"},{"t":"text","v":"，在 catch 里收尾后 return；在跑计算时不会自动停，必须自己看 "},{"t":"code","v":"isInterrupted()"},{"t":"text","v":"，为 true 就退出。"}]},{"type":"p","inlines":[{"t":"text","v":"用 "},{"t":"code","v":"stop()"},{"t":"text","v":"：强制掐死线程。"},{"t":"code","v":"stop"},{"t":"text","v":"、"},{"t":"code","v":"suspend"},{"t":"text","v":"、"},{"t":"code","v":"resume"},{"t":"text","v":" 都已废弃，锁可能来不及放，对象停在半中间，绝对不要用。"}]},{"type":"p","inlines":[{"t":"text","v":"生产里更稳的是「标志位 + interrupt」一起用：只改标志，线程若正卡在 "},{"t":"code","v":"sleep"},{"t":"text","v":" 上，要等到睡醒才看见；先 "},{"t":"code","v":"interrupt"},{"t":"text","v":" 把它从阻塞里叫醒，再在 catch 里把标志置上、正常退出。"}]},{"type":"code","text":"class MyThread extends Thread {\n    volatile boolean stop = false;\n\n    public void run() {\n        while (!stop) {\n            System.out.println(getName() + \" is running\");\n            try {\n                Thread.sleep(1000);\n            } catch (InterruptedException e) {\n                // 从阻塞里被叫醒，改共享标志，让循环能退出\n                stop = true;\n            }\n        }\n        System.out.println(getName() + \" is exiting...\");\n    }\n}\n\n// 主线程：先改标志，再 interrupt 叫醒 sleep\nm1.stop = true;\nm1.interrupt();"},{"type":"p","inlines":[{"t":"text","v":"线程池用 "},{"t":"code","v":"shutdown()"},{"t":"text","v":" 不再接新任务，等跑完；"},{"t":"code","v":"shutdownNow()"},{"t":"text","v":" 会 interrupt 正在跑的任务，任务同样要响应中断。"},{"t":"code","v":"Future.cancel(true)"},{"t":"text","v":" 也是对那条任务发 interrupt。"}]}]},{"id":"thread-如何停止一个正在运行的线程-stop-为什么不能用","module":"thread","title":"stop 为什么不能用","level":"extra","summary":"它立刻终止线程，finally、解锁都不保证走完。共享对象可能只改了一半，别的线程再…","blocks":[{"type":"p","inlines":[{"t":"text","v":"它立刻终止线程，"},{"t":"code","v":"finally"},{"t":"text","v":"、解锁都不保证走完。共享对象可能只改了一半，别的线程再进来就是坏数据。所以 JDK 标成废弃，面试里要主动说「知道有这个方法，但不能用」。"}]}],"parentId":"thread-如何停止一个正在运行的线程"},{"id":"thread-如何停止一个正在运行的线程-interrupt-一定会让线程停下来吗","module":"thread","title":"interrupt 一定会让线程停下来吗","level":"extra","summary":"不会。它只是设中断标记，或叫醒正在等待的线程。线程不检查标记、catch 了异常又吞…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不会。它只是设中断标记，或叫醒正在等待的线程。线程不检查标记、catch 了异常又吞掉继续跑，就停不下来。所以写任务时必须响应中断，这是约定，不是强制。"}]}],"parentId":"thread-如何停止一个正在运行的线程"},{"id":"thread-如何停止一个正在运行的线程-为什么标志位还要再调-interrupt","module":"thread","title":"为什么标志位还要再调 interrupt","level":"extra","summary":"volatile 标志只在线程下次读到时才生效。如果正堵在 sleep / wait…","blocks":[{"type":"p","inlines":[{"t":"code","v":"volatile"},{"t":"text","v":" 标志只在线程下次读到时才生效。如果正堵在 "},{"t":"code","v":"sleep"},{"t":"text","v":" / "},{"t":"code","v":"wait"},{"t":"text","v":" / "},{"t":"code","v":"join"},{"t":"text","v":" 上，不 interrupt 就一直睡，标志改了也看不见。"},{"t":"code","v":"interrupt"},{"t":"text","v":" 把阻塞打断，抛 "},{"t":"code","v":"InterruptedException"},{"t":"text","v":"，再在 catch 里把标志置 true 或直接 return，才能及时停。"}]}],"parentId":"thread-如何停止一个正在运行的线程"},{"id":"thread-如何停止一个正在运行的线程-被中断后要不要恢复中断标记","module":"thread","title":"被中断后要不要恢复中断标记","level":"extra","summary":"sleep 抛异常后标记会被清掉。如果你不在这里结束线程，而是把异常往外传或交给上层…","blocks":[{"type":"p","inlines":[{"t":"code","v":"sleep"},{"t":"text","v":" 抛异常后标记会被清掉。如果你不在这里结束线程，而是把异常往外传或交给上层判断，要再调一次 "},{"t":"code","v":"Thread.currentThread().interrupt()"},{"t":"text","v":"，把标记设回去。否则上层不知道你被中断过。"}]}],"parentId":"thread-如何停止一个正在运行的线程"},{"id":"thread-notify和notifyAll有什么区别","module":"thread","title":"notify和notifyAll有什么区别","level":"core","summary":"两者都是 Object 上的方法，必须在持有对象监视器的同步块里调用，用来叫醒在这个…","blocks":[{"type":"p","inlines":[{"t":"text","v":"两者都是 "},{"t":"code","v":"Object"},{"t":"text","v":" 上的方法，必须在持有对象监视器的同步块里调用，用来叫醒在这个对象上 "},{"t":"code","v":"wait"},{"t":"text","v":" 着的线程。区别是叫醒几个。"}]},{"type":"p","inlines":[{"t":"code","v":"notify()"},{"t":"text","v":"：只从等待队列里随便挑一个（实现相关，不能当公平队列用）挪到入口队列，准备去抢锁。其他还在 wait 的线程继续睡。"}]},{"type":"p","inlines":[{"t":"code","v":"notifyAll()"},{"t":"text","v":"：把所有在这个对象上 wait 的线程都叫醒，大家一起去抢锁。谁先抢到谁跑，条件不满足的再 wait。"}]},{"type":"p","inlines":[{"t":"text","v":"什么时候用哪个。等待方条件一样、叫醒一个就够，比如一个生产者对应一个消费者，可以用 "},{"t":"code","v":"notify"},{"t":"text","v":"。多个线程等的条件不一样，或者不确定谁该醒，用 "},{"t":"code","v":"notifyAll"},{"t":"text","v":" 更安全。生产者-消费者里常有「队列满了等」和「队列空了等」两种，只 "},{"t":"code","v":"notify"},{"t":"text","v":" 可能叫醒同类线程，真正该干活的还在睡，造成假死。这时必须 "},{"t":"code","v":"notifyAll"},{"t":"text","v":"，或者改用 "},{"t":"code","v":"Condition"},{"t":"text","v":" 的多个条件队列。"}]},{"type":"p","inlines":[{"t":"text","v":"注意：被叫醒不等于立刻跑，还要重新抢到锁，并且要用 "},{"t":"code","v":"while"},{"t":"text","v":" 再判断一次等待条件，防止虚假唤醒。"}]}]},{"id":"thread-notify和notifyAll有什么区别-为什么-wait-要用-while-判断条件","module":"thread","title":"为什么 wait 要用 while 判断条件","level":"extra","summary":"被 notify / notifyAll 叫醒后，可能条件还不成立，也可能是虚假唤醒…","blocks":[{"type":"p","inlines":[{"t":"text","v":"被 "},{"t":"code","v":"notify"},{"t":"text","v":" / "},{"t":"code","v":"notifyAll"},{"t":"text","v":" 叫醒后，可能条件还不成立，也可能是虚假唤醒。"},{"t":"code","v":"if"},{"t":"text","v":" 判断一次就往下跑会出错。标准写法是 "},{"t":"code","v":"while (!条件) { obj.wait(); }"},{"t":"text","v":"，醒来再检查一遍。"}]}],"parentId":"thread-notify和notifyAll有什么区别"},{"id":"thread-notify和notifyAll有什么区别-notify-会造成假死吗","module":"thread","title":"notify 会造成假死吗","level":"extra","summary":"会。多个生产者、多个消费者共用一把锁时，notify 可能叫醒另一个生产者，而消费者…","blocks":[{"type":"p","inlines":[{"t":"text","v":"会。多个生产者、多个消费者共用一把锁时，"},{"t":"code","v":"notify"},{"t":"text","v":" 可能叫醒另一个生产者，而消费者还在 wait，队列又满了，大家互相等。"},{"t":"code","v":"notifyAll"},{"t":"text","v":" 让所有人醒过来重新抢，能避免这种叫错人。更干净的做法是 "},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 配两个 "},{"t":"code","v":"Condition"},{"t":"text","v":"：不满、不空，各叫各的。"}]}],"parentId":"thread-notify和notifyAll有什么区别"},{"id":"thread-notify和notifyAll有什么区别-wait、notify-和-sleep-有什么区别","module":"thread","title":"wait、notify 和 sleep 有什么区别","level":"extra","summary":"详见 [sleep和wait有什么区别](./sleep和wait有什么区别.md)…","blocks":[{"type":"p","inlines":[{"t":"text","v":"详见 [sleep和wait有什么区别](./sleep和wait有什么区别.md)。"},{"t":"code","v":"wait"},{"t":"text","v":" 放锁、等 notify；"},{"t":"code","v":"sleep"},{"t":"text","v":" 不放锁、时间到自己醒。协作用 wait，延时用 sleep。"}]}],"parentId":"thread-notify和notifyAll有什么区别"},{"id":"thread-notify和notifyAll有什么区别-为什么-wait、notify、notifyAll-不在-Thread-类里","module":"thread","title":"为什么 wait、notify、notifyAll 不在 Thread 类里","level":"extra","summary":"因为锁是对象的，不是线程的。每个对象都有自己的监视器，线程要等的是「某把对象锁上的条…","blocks":[{"type":"p","inlines":[{"t":"text","v":"因为锁是对象的，不是线程的。每个对象都有自己的监视器，线程要等的是「某把对象锁上的条件」，不是「某个线程本身」。"},{"t":"code","v":"wait"},{"t":"text","v":" / "},{"t":"code","v":"notify"},{"t":"text","v":" / "},{"t":"code","v":"notifyAll"},{"t":"text","v":" 是锁级别的操作，所以挂在 "},{"t":"code","v":"Object"},{"t":"text","v":" 上。如果放在 "},{"t":"code","v":"Thread"},{"t":"text","v":" 里，就说不清你在等哪把锁、要叫醒等在哪把锁上的线程。"}]}],"parentId":"thread-notify和notifyAll有什么区别"},{"id":"thread-notify和notifyAll有什么区别-为什么-wait-和-notify-必须在同步块里调用","module":"thread","title":"为什么 wait 和 notify 必须在同步块里调用","level":"extra","summary":"调用时当前线程必须已经持有这个对象的监视器锁，否则会抛 IllegalMonitor…","blocks":[{"type":"p","inlines":[{"t":"text","v":"调用时当前线程必须已经持有这个对象的监视器锁，否则会抛 "},{"t":"code","v":"IllegalMonitorStateException"},{"t":"text","v":"。"},{"t":"code","v":"wait"},{"t":"text","v":" 要把锁释放掉再进入等待集，没有锁就谈不上释放；"},{"t":"code","v":"notify"},{"t":"text","v":" / "},{"t":"code","v":"notifyAll"},{"t":"text","v":" 也是改这把锁对应的等待队列，必须拿着锁才能改。另外，等的通常是某个共享状态变了，状态的判断和修改本身就该在同步块里，否则 wait 和 notify 之间会有竞态：一边刚判断完要 wait，另一边的 notify 已经发过了，信号就丢了。"}]}],"parentId":"thread-notify和notifyAll有什么区别"},{"id":"thread-sleep和wait有什么区别","module":"thread","title":"sleep和wait有什么区别","level":"core","summary":"sleep() 在 Thread 类里，wait() 在 Object 类里。一个是…","blocks":[{"type":"p","inlines":[{"t":"code","v":"sleep()"},{"t":"text","v":" 在 "},{"t":"code","v":"Thread"},{"t":"text","v":" 类里，"},{"t":"code","v":"wait()"},{"t":"text","v":" 在 "},{"t":"code","v":"Object"},{"t":"text","v":" 类里。一个是线程自己睡一会儿，一个是在某把对象锁上等条件。"}]},{"type":"p","inlines":[{"t":"code","v":"sleep"},{"t":"text","v":"：让当前线程暂停指定时间，把 CPU 让出去，时间到了自己醒。调用时不要求持有锁；如果碰巧拿着锁，不会释放，别人还是进不来同步块。纯粹做延时、限速。"}]},{"type":"p","inlines":[{"t":"code","v":"wait"},{"t":"text","v":"：必须已经持有这个对象的监视器锁，否则 "},{"t":"code","v":"IllegalMonitorStateException"},{"t":"text","v":"。调用后释放这把锁，线程进入该对象的等待集。只有别人对同一对象 "},{"t":"code","v":"notify"},{"t":"text","v":" / "},{"t":"code","v":"notifyAll"},{"t":"text","v":"（或 "},{"t":"code","v":"wait(超时)"},{"t":"text","v":" 到期、被 interrupt）后，它才进入口队列去重新抢锁，抢到才能继续跑。用来做线程间协作：等某个共享状态变了再往下走。"}]},{"type":"p","inlines":[{"t":"text","v":"被叫醒不等于立刻执行。"},{"t":"code","v":"wait"},{"t":"text","v":" 回来后还要再抢锁，并用 "},{"t":"code","v":"while"},{"t":"text","v":" 重新判断条件。"},{"t":"code","v":"sleep"},{"t":"text","v":" 醒了如果原来拿着锁，锁还在自己手里。"}]},{"type":"p","inlines":[{"t":"text","v":"两者都可以响应中断：睡或等的时候 "},{"t":"code","v":"interrupt"},{"t":"text","v":" 会抛 "},{"t":"code","v":"InterruptedException"},{"t":"text","v":"。"}]}]},{"id":"thread-sleep和wait有什么区别-sleep-会释放锁吗","module":"thread","title":"sleep 会释放锁吗","level":"extra","summary":"不会。这是和 wait 最常考的一点。在 synchronized 里 sleep，…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不会。这是和 "},{"t":"code","v":"wait"},{"t":"text","v":" 最常考的一点。在 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 里 "},{"t":"code","v":"sleep"},{"t":"text","v":"，其他线程仍然拿不到这把锁，等于占着锁睡觉，容易把并发度打没。要等条件，用 "},{"t":"code","v":"wait"},{"t":"text","v":"，不要用 "},{"t":"code","v":"sleep"},{"t":"text","v":" 去轮询。"}]}],"parentId":"thread-sleep和wait有什么区别"},{"id":"thread-sleep和wait有什么区别-wait-之后怎么才能继续运行","module":"thread","title":"wait 之后怎么才能继续运行","level":"extra","summary":"先被 notify / notifyAll 从等待集挪到入口队列（或超时、中断），再…","blocks":[{"type":"p","inlines":[{"t":"text","v":"先被 "},{"t":"code","v":"notify"},{"t":"text","v":" / "},{"t":"code","v":"notifyAll"},{"t":"text","v":" 从等待集挪到入口队列（或超时、中断），再重新竞争对象锁，拿到锁才从 "},{"t":"code","v":"wait"},{"t":"text","v":" 返回。只 notify 不给锁，线程还是过不去。"}]}],"parentId":"thread-sleep和wait有什么区别"},{"id":"thread-sleep和wait有什么区别-为什么-wait-定义在-Object-上，sleep-定义在-Thread-上","module":"thread","title":"为什么 wait 定义在 Object 上，sleep 定义在 Thread 上","level":"extra","summary":"sleep 管的是「这条线程停多久」，跟哪把锁无关。wait 管的是「在这把对象锁上…","blocks":[{"type":"p","inlines":[{"t":"code","v":"sleep"},{"t":"text","v":" 管的是「这条线程停多久」，跟哪把锁无关。"},{"t":"code","v":"wait"},{"t":"text","v":" 管的是「在这把对象锁上等条件」，锁属于对象，所以在 "},{"t":"code","v":"Object"},{"t":"text","v":" 上。"}]}],"parentId":"thread-sleep和wait有什么区别"},{"id":"thread-说说JMM内存模型的理解","module":"thread","title":"说说JMM内存模型的理解","level":"core","summary":"JMM 是 Java 内存模型，规定多线程怎么访问共享变量。它不是堆、栈那种运行时数…","blocks":[{"type":"p","inlines":[{"t":"text","v":"JMM 是 Java 内存模型，规定多线程怎么访问共享变量。它不是堆、栈那种运行时数据区，而是一套读写规则。"}]},{"type":"p","inlines":[{"t":"text","v":"为什么要有它：CPU 算得快，内存 IO 慢，所以中间加了高速缓存。线程各自在缓存里改副本，算完再刷回内存，吞吐上去了，但多核之间会出现缓存不一致：你改了，我这边缓存还是旧值。编译器和处理器还会重排指令。JMM 就是来管这两件事的。"}]},{"type":"p","inlines":[{"t":"text","v":"缓存一致性：硬件有 MESI 这类协议，JMM 再用主内存、工作内存把这件事抽象出来。共享变量在主内存，每个线程工作内存里是副本。没有同步时，一个线程写回了，另一个线程不一定看见。"}]},{"type":"p","inlines":[{"t":"text","v":"As-if-serial：单线程里可以重排，但结果必须和按代码顺序执行一样。有数据依赖的不能乱排。它只管单线程；跨线程还要靠后面的 happens-before。"}]},{"type":"p","inlines":[{"t":"text","v":"多线程访问规则最后落在三要素和 happens-before 上。"}]},{"type":"p","inlines":[{"t":"text","v":"可见性：一个线程改完，其他线程要能读到新值。"},{"t":"code","v":"volatile"},{"t":"text","v":" 写刷回主内存、读从主内存加载；"},{"t":"code","v":"synchronized"},{"t":"text","v":" 解锁前写回，加锁后重新读。"}]},{"type":"p","inlines":[{"t":"text","v":"原子性：一组操作中间不能被拆开。"},{"t":"code","v":"synchronized"},{"t":"text","v":"、Lock 能保证；"},{"t":"code","v":"volatile"},{"t":"text","v":" 只保证单次读写，"},{"t":"code","v":"i++"},{"t":"text","v":" 不行。"}]},{"type":"p","inlines":[{"t":"text","v":"有序性：两种重排都会打乱代码顺序。编译器重排是 javac/JIT 为了优化换指令位置；处理器重排是 CPU 乱序执行、写缓冲。单线程有 as-if-serial 兜着，多线程必须靠内存屏障和锁。"},{"t":"code","v":"volatile"},{"t":"text","v":" 插屏障禁一部分重排，"},{"t":"code","v":"synchronized"},{"t":"text","v":" 靠同一把锁串行。"}]},{"type":"p","inlines":[{"t":"text","v":"happens-before：如果 A happens-before B，A 的结果对 B 一定可见，也不能把 A 排到 B 后面。常见有程序次序、unlock happens-before 后面的 lock、volatile 写 happens-before 读、线程 start/join，以及传递性。细节见「说说happens-before规则」。"}]}]},{"id":"thread-说说JMM内存模型的理解-JMM-和-JVM-运行时数据区有什么区别","module":"thread","title":"JMM 和 JVM 运行时数据区有什么区别","level":"extra","summary":"运行时数据区讲的是内存怎么分块：堆、栈、方法区、程序计数器。JMM 讲的是这些共享变…","blocks":[{"type":"p","inlines":[{"t":"text","v":"运行时数据区讲的是内存怎么分块：堆、栈、方法区、程序计数器。JMM 讲的是这些共享变量在多线程下怎么同步、怎么保证可见。一个管「放哪」，一个管「怎么看见」。"}]}],"parentId":"thread-说说JMM内存模型的理解"},{"id":"thread-说说JMM内存模型的理解-volatile-怎么保证可见性和有序性","module":"thread","title":"volatile 怎么保证可见性和有序性","level":"extra","summary":"写 volatile 变量时，会把工作内存里的值刷回主内存，并插入写屏障，阻止后面的…","blocks":[{"type":"p","inlines":[{"t":"text","v":"写 "},{"t":"code","v":"volatile"},{"t":"text","v":" 变量时，会把工作内存里的值刷回主内存，并插入写屏障，阻止后面的写跑到这个写前面。读时从主内存加载，并插入读屏障，阻止后面的读跑到这个读前面。所以它能保证可见性，也能禁止一部分重排，但不保证复合操作的原子性。"}]}],"parentId":"thread-说说JMM内存模型的理解"},{"id":"thread-说说JMM内存模型的理解-为什么要有工作内存，直接改主内存不行吗","module":"thread","title":"为什么要有工作内存，直接改主内存不行吗","level":"extra","summary":"CPU 有多级缓存，线程不可能每次都直接读写主存，否则太慢。JMM 用工作内存抽象这…","blocks":[{"type":"p","inlines":[{"t":"text","v":"CPU 有多级缓存，线程不可能每次都直接读写主存，否则太慢。JMM 用工作内存抽象这件事：线程在本地副本上算，再按规则刷回主内存。代价就是可见性不再自动成立，所以才需要 "},{"t":"code","v":"volatile"},{"t":"text","v":"、锁和 happens-before。"}]}],"parentId":"thread-说说JMM内存模型的理解"},{"id":"thread-说说JMM内存模型的理解-缓存一致性和-JMM-是一回事吗","module":"thread","title":"缓存一致性和 JMM 是一回事吗","level":"extra","summary":"不是一层。缓存一致性是硬件协议，管多核 Cache 里同一行数据怎么同步。JMM 是…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不是一层。缓存一致性是硬件协议，管多核 Cache 里同一行数据怎么同步。JMM 是语言规范，管 Java 线程什么时候必须看见别人的写入。JMM 靠 volatile、锁去用到硬件的锁和内存屏障，最终落到缓存一致性上，但面试里不要把 MESI 和 JMM 说成同一个东西。"}]}],"parentId":"thread-说说JMM内存模型的理解"},{"id":"thread-说说JMM内存模型的理解-主内存和工作内存之间有哪八个操作","module":"thread","title":"主内存和工作内存之间有哪八个操作","level":"extra","summary":"规范里用八个原子操作描述交互：lock / unlock 在主内存给变量加解锁；re…","blocks":[{"type":"p","inlines":[{"t":"text","v":"规范里用八个原子操作描述交互："},{"t":"code","v":"lock"},{"t":"text","v":" / "},{"t":"code","v":"unlock"},{"t":"text","v":" 在主内存给变量加解锁；"},{"t":"code","v":"read"},{"t":"text","v":" / "},{"t":"code","v":"load"},{"t":"text","v":" 把主内存值搬进工作内存；"},{"t":"code","v":"use"},{"t":"text","v":" / "},{"t":"code","v":"assign"},{"t":"text","v":" 是执行引擎读用、写回工作内存；"},{"t":"code","v":"store"},{"t":"text","v":" / "},{"t":"code","v":"write"},{"t":"text","v":" 再把工作内存写回主内存。面试不用背实现，知道「线程不直接改主内存，靠这套读写链路」即可，和可见性、"},{"t":"code","v":"volatile"},{"t":"text","v":" 刷写对得上。"}]}],"parentId":"thread-说说JMM内存模型的理解"},{"id":"thread-说说happens-before规则","module":"thread","title":"说说happens-before规则","level":"core","summary":"happens-before 是 JMM 用来判断「前面的操作结果，后面的操作一定能…","blocks":[{"type":"p","inlines":[{"t":"text","v":"happens-before 是 JMM 用来判断「前面的操作结果，后面的操作一定能看见」的规则。它不保证墙上时钟谁先发生，只保证可见性和有序性：如果 A happens-before B，A 的写入对 B 一定可见，而且不能把 A 重排到 B 后面。"}]},{"type":"p","inlines":[{"t":"text","v":"面试常背这几条："}]},{"type":"p","inlines":[{"t":"text","v":"程序次序：同一个线程里，前面的操作 happens-before 后面的操作。单线程看起来就是按代码顺序执行。"}]},{"type":"p","inlines":[{"t":"text","v":"锁规则：对同一把锁，unlock happens-before 后面的 lock。所以线程 A 解锁前写的共享变量，线程 B 加锁后一定能看见。"}]},{"type":"p","inlines":[{"t":"text","v":"volatile 规则：对同一个 "},{"t":"code","v":"volatile"},{"t":"text","v":" 变量，写 happens-before 后面的读。写会刷回主内存，读会从主内存拿最新值。"}]},{"type":"p","inlines":[{"t":"text","v":"线程启动：线程 A 执行 "},{"t":"code","v":"B.start()"},{"t":"text","v":" happens-before 线程 B 里的任何操作。B 启动后能看见 A 在 start 之前做的事。"}]},{"type":"p","inlines":[{"t":"text","v":"线程终止：线程 B 里的任何操作 happens-before 线程 A 从 "},{"t":"code","v":"B.join()"},{"t":"text","v":" 成功返回。join 回来后一定能看见 B 已经做完的修改。"}]},{"type":"p","inlines":[{"t":"text","v":"中断：对线程 "},{"t":"code","v":"interrupt()"},{"t":"text","v":" happens-before 被中断线程检测到中断，比如 "},{"t":"code","v":"interrupted()"},{"t":"text","v":" 返回 true。"}]},{"type":"p","inlines":[{"t":"text","v":"传递性：A happens-before B，B happens-before C，则 A happens-before C。锁、volatile、start/join 能把单线程里的写入「传递」给另一个线程。"}]}]},{"id":"thread-说说happens-before规则-happens-before-是时间上谁先发生吗","module":"thread","title":"happens-before 是时间上谁先发生吗","level":"extra","summary":"不是。它是可见性规则，不是计时器。A happens-before B，不代表 A …","blocks":[{"type":"p","inlines":[{"t":"text","v":"不是。它是可见性规则，不是计时器。A happens-before B，不代表 A 的代码一定在真实时间上先跑完，只代表 B 执行时一定能看到 A 的结果。反过来，墙上时钟 A 先发生，如果中间没有 happens-before，B 也不一定看得到。"}]}],"parentId":"thread-说说happens-before规则"},{"id":"thread-说说happens-before规则-没有-happens-before-就一定看不见吗","module":"thread","title":"没有 happens-before 就一定看不见吗","level":"extra","summary":"不一定。没有这条规则只是「不保证看见」，运行时可能碰巧刷回主内存，结果对了，但不能依…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不一定。没有这条规则只是「不保证看见」，运行时可能碰巧刷回主内存，结果对了，但不能依赖。并发里要的是保证，所以共享变量要么加锁，要么用 "},{"t":"code","v":"volatile"},{"t":"text","v":"，要么走 start/join 这些已经规定好的关系。"}]}],"parentId":"thread-说说happens-before规则"},{"id":"thread-说说happens-before规则-as-if-serial-是什么，和-happens-before-有什么关系","module":"thread","title":"as-if-serial 是什么，和 happens-before 有什么关系","level":"extra","summary":"as-if-serial 的意思是「看起来像按代码顺序执行」。编译器和 CPU 为了…","blocks":[{"type":"p","inlines":[{"t":"text","v":"as-if-serial 的意思是「看起来像按代码顺序执行」。编译器和 CPU 为了提高速度可以重排指令，但在单线程里，重排后的结果必须和按书写顺序执行一模一样。有数据依赖的操作不能乱排，比如先 "},{"t":"code","v":"a = 1"},{"t":"text","v":" 再 "},{"t":"code","v":"b = a"},{"t":"text","v":"，这两步不能对调。"}]},{"type":"p","inlines":[{"t":"text","v":"它和 happens-before 的关系是：as-if-serial 只管单线程的执行结果；happens-before 还要管多线程之间谁的写入必须可见。单线程里，程序次序规则和 as-if-serial 是对上的。多线程只靠 as-if-serial 不够，两个线程各看各的代码顺序，没有锁、"},{"t":"code","v":"volatile"},{"t":"text","v":"、start/join 这些 happens-before，就没有跨线程的可见性保证。"}]}],"parentId":"thread-说说happens-before规则"},{"id":"thread-说说volatile","module":"thread","title":"说说volatile","level":"core","summary":"volatile 是 Java 的轻量同步关键字，管可见性和有序性，不管复合操作的原…","blocks":[{"type":"p","inlines":[{"t":"code","v":"volatile"},{"t":"text","v":" 是 Java 的轻量同步关键字，管可见性和有序性，不管复合操作的原子性。它比 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 轻，没有互斥，不能替代锁。"}]},{"type":"p","inlines":[{"t":"text","v":"可见性：写 "},{"t":"code","v":"volatile"},{"t":"text","v":" 会把工作内存里的值刷回主内存；读会从主内存重新加载，不用过期副本。happens-before 里：对同一个 "},{"t":"code","v":"volatile"},{"t":"text","v":" 变量，写 happens-before 后面的读。所以一个线程改了 flag，另一个线程一定能看见新值。"}]},{"type":"p","inlines":[{"t":"text","v":"有序性："},{"t":"code","v":"volatile"},{"t":"text","v":" 读写会插内存屏障，禁止一部分重排。写之前的操作不能排到这写后面，读之后的操作不能排到这读前面。DCL 单例里实例要用 "},{"t":"code","v":"volatile"},{"t":"text","v":"，就是防止构造过程被重排，别的线程看到半初始化的对象。"}]},{"type":"p","inlines":[{"t":"text","v":"原子性：只保证这一次读或这一次写是原子的。"},{"t":"code","v":"i++"},{"t":"text","v":" 是读、加、写三步，中间别人也能插进来，所以 "},{"t":"code","v":"volatile int"},{"t":"text","v":" 做计数不行，要用 "},{"t":"code","v":"AtomicInteger"},{"t":"text","v":" 或加锁。"}]},{"type":"p","inlines":[{"t":"text","v":"底层可以记：写会带 lock 前缀，锁总线或锁缓存行，触发缓存一致性，让别的核的副本失效；同时屏障挡住乱序。常见屏障类别可对一下：LoadLoad、StoreStore、LoadStore、StoreLoad，分别约束读读、写写、读写、写读的顺序。字段在字节码 access flag 里会带 "},{"t":"code","v":"ACC_VOLATILE"},{"t":"text","v":"。面试说到屏障和主内存刷回就够，不必展开 MESI 时序。"}]},{"type":"p","inlines":[{"t":"text","v":"适用：状态开关、完成标志、安全发布（DCL）。要互斥改同一份数据，还是 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 或 Lock。"}]}]},{"id":"thread-说说volatile-volatile-和-synchronized-有什么区别","module":"thread","title":"volatile 和 synchronized 有什么区别","level":"extra","summary":"作用范围不同。volatile 只能修饰变量，告诉 JVM 这个值要以主内存为准，工…","blocks":[{"type":"p","inlines":[{"t":"text","v":"作用范围不同。"},{"t":"code","v":"volatile"},{"t":"text","v":" 只能修饰变量，告诉 JVM 这个值要以主内存为准，工作内存里的副本不能当最终结果。"},{"t":"code","v":"synchronized"},{"t":"text","v":" 锁的是对象监视器，可以锁方法、代码块，也能锁类对象，粒度比变量大。"}]},{"type":"p","inlines":[{"t":"text","v":"可见性和原子性不同。"},{"t":"code","v":"volatile"},{"t":"text","v":" 保证修改对其它线程可见，也保证对这个变量的部分有序，但不保证 "},{"t":"code","v":"i++"},{"t":"text","v":" 这类复合操作的原子性。"},{"t":"code","v":"synchronized"},{"t":"text","v":" 进入临界区后既可见又互斥，临界区内的操作可以当成原子完成。"}]},{"type":"p","inlines":[{"t":"text","v":"会不会阻塞不同。"},{"t":"code","v":"volatile"},{"t":"text","v":" 读写不互斥，不会让线程卡住等锁。"},{"t":"code","v":"synchronized"},{"t":"text","v":" 抢不到锁就会阻塞，可能上下文切换。"}]},{"type":"p","inlines":[{"t":"text","v":"和编译器、重排的关系不同。"},{"t":"code","v":"volatile"},{"t":"text","v":" 读写会插屏障，禁止把前后无关指令跨过这次读写重排。"},{"t":"code","v":"synchronized"},{"t":"text","v":" 靠加锁、解锁建立 happens-before，解锁前的写入对下一个加锁的线程可见；临界区内部在不破坏监视器语义的前提下，仍可能做一些优化重排。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么选：读多写少、只当状态标志，用 "},{"t":"code","v":"volatile"},{"t":"text","v":"。要互斥改同一份数据、要保证复合操作，用 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 或 Lock、原子类。"}]}],"parentId":"thread-说说volatile"},{"id":"thread-说说volatile-为什么-DCL-单例的实例要加-volatile","module":"thread","title":"为什么 DCL 单例的实例要加 volatile","level":"extra","summary":"instance = new Singleton() 会拆成分配内存、初始化、把引用…","blocks":[{"type":"p","inlines":[{"t":"code","v":"instance = new Singleton()"},{"t":"text","v":" 会拆成分配内存、初始化、把引用指向这块内存。没有 "},{"t":"code","v":"volatile"},{"t":"text","v":"，引用赋值可能排到初始化前面。线程 A 刚写了引用，线程 B 判断 instance 非空，拿到的却是还没跑完构造的对象。"},{"t":"code","v":"volatile"},{"t":"text","v":" 挡住这步重排，发布出去的一定是构造完的。"}]}],"parentId":"thread-说说volatile"},{"id":"thread-说说volatile-volatile-能保证-long、double-的读写原子吗","module":"thread","title":"volatile 能保证 long、double 的读写原子吗","level":"extra","summary":"规范里 64 位的 long/double 普通读写可能拆成两次 32 位，不是原子…","blocks":[{"type":"p","inlines":[{"t":"text","v":"规范里 64 位的 "},{"t":"code","v":"long"},{"t":"text","v":"/"},{"t":"code","v":"double"},{"t":"text","v":" 普通读写可能拆成两次 32 位，不是原子的。声明成 "},{"t":"code","v":"volatile"},{"t":"text","v":" 之后，读写必须原子。这和 "},{"t":"code","v":"i++"},{"t":"text","v":" 不是一回事："},{"t":"code","v":"volatile long"},{"t":"text","v":" 的一次赋值是原子的，"},{"t":"code","v":"count++"},{"t":"text","v":" 仍然不是。"}]}],"parentId":"thread-说说volatile"},{"id":"thread-详细说说synchronized","module":"thread","title":"详细说说synchronized","level":"core","summary":"synchronized 是 Java 的关键字，用来做互斥同步。同一时刻只有一个线…","blocks":[{"type":"p","inlines":[{"t":"code","v":"synchronized"},{"t":"text","v":" 是 Java 的关键字，用来做互斥同步。同一时刻只有一个线程能拿到对象的监视器锁，进临界区；解锁时把写入刷回主内存，下一个加锁的线程一定能看见。可见性、原子性、有序性它都能管，比 "},{"t":"code","v":"volatile"},{"t":"text","v":" 重，但能保证复合操作不被拆开。"}]},{"type":"p","inlines":[{"t":"text","v":"用法分同步方法和同步代码块。"}]},{"type":"p","inlines":[{"t":"text","v":"同步实例方法、或 "},{"t":"code","v":"synchronized (this)"},{"t":"text","v":" / "},{"t":"code","v":"synchronized (实例)"},{"t":"text","v":"：锁的是实例对象。不同实例各有各的锁，互不影响。"}]},{"type":"p","inlines":[{"t":"text","v":"同步静态方法、或 "},{"t":"code","v":"synchronized (Xxx.class)"},{"t":"text","v":"：锁的是类对象，整类共用一把，相当于全局锁。实例锁和类锁不是同一把，两者可以并行。"}]},{"type":"p","inlines":[{"t":"text","v":"代码块比整方法灵活：锁哪个对象、锁多大范围，自己定。锁得越小，并发越好；锁错对象等于没锁。"}]},{"type":"p","inlines":[{"t":"text","v":"底层是监视器锁。同步代码块编译后大致是 "},{"t":"code","v":"monitorenter"},{"t":"text","v":" 进、"},{"t":"code","v":"monitorexit"},{"t":"text","v":" 出，异常路径也会配 "},{"t":"code","v":"monitorexit"},{"t":"text","v":"，避免锁飞了。同步方法不显式插这两条，靠方法上的 "},{"t":"code","v":"ACC_SYNCHRONIZED"},{"t":"text","v":" 标志，进入、退出时由 JVM 加解锁。对象头 Mark Word 里记着锁状态，Monitor（ObjectMonitor）里有入口队列、等待队列，配合 "},{"t":"code","v":"wait"},{"t":"text","v":" / "},{"t":"code","v":"notify"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"锁不是一上来就重量级。HotSpot 会升级："}]},{"type":"p","inlines":[{"t":"text","v":"偏向锁：第一次只有一个线程进，Mark Word 记下线程 ID，以后这个线程再进几乎不用 CAS，适合几乎无竞争。"}]},{"type":"p","inlines":[{"t":"text","v":"轻量级锁：出现竞争苗头时，线程在自己栈上建 Lock Record，用 CAS 把对象头指过去。抢得到就还是用户态；适合短暂竞争。"}]},{"type":"p","inlines":[{"t":"text","v":"重量级锁：CAS 一直失败，膨胀成重量级，线程进操作系统互斥量，会阻塞、唤醒，开销最大。"}]},{"type":"p","inlines":[{"t":"text","v":"锁一般只升级不降级（偏向可以撤销）。JDK 15 起偏向锁默认关了，面试提一句「传统升级路径是偏 → 轻 → 重」即可。"}]},{"type":"p","inlines":[{"t":"text","v":"还有几项优化。锁消除：逃逸分析证明锁对象不会逃出线程，同步可以拿掉。锁粗化：连续好几个锁同一对象，合并成一次加解锁，少几次进出。自适应自旋：抢不到锁时先空转一阵，空转时长会按历史成败调整，避免动不动挂起。"}]}]},{"id":"thread-详细说说synchronized-同步方法和同步代码块怎么选","module":"thread","title":"同步方法和同步代码块怎么选","level":"extra","summary":"只保护方法里一小段，用代码块，锁粒度更小。整段逻辑都要互斥，直接同步方法更干净。静态…","blocks":[{"type":"p","inlines":[{"t":"text","v":"只保护方法里一小段，用代码块，锁粒度更小。整段逻辑都要互斥，直接同步方法更干净。静态数据、全局缓存用类锁；只保护当前实例状态用实例锁。千万别锁字符串字面量这类会被共享的对象。"}]}],"parentId":"thread-详细说说synchronized"},{"id":"thread-详细说说synchronized-偏向锁、轻量级锁、重量级锁各自适合什么","module":"thread","title":"偏向锁、轻量级锁、重量级锁各自适合什么","level":"extra","summary":"几乎总是同一个线程进：偏向。竞争少、临界区很短：轻量级，自旋一下就过去。竞争激烈、临…","blocks":[{"type":"p","inlines":[{"t":"text","v":"几乎总是同一个线程进：偏向。竞争少、临界区很短：轻量级，自旋一下就过去。竞争激烈、临界区长：重量级，该阻塞就阻塞，空转反而浪费 CPU。"}]}],"parentId":"thread-详细说说synchronized"},{"id":"thread-详细说说synchronized-synchronized-和-ReentrantLock-怎么选","module":"thread","title":"synchronized 和 ReentrantLock 怎么选","level":"extra","summary":"synchronized 是关键字，自动加解锁，JVM 优化多，代码短，一般场景够用…","blocks":[{"type":"p","inlines":[{"t":"code","v":"synchronized"},{"t":"text","v":" 是关键字，自动加解锁，JVM 优化多，代码短，一般场景够用。"},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 是 API：可中断、可限时、公平锁、多个 Condition。需要这些能力再上 Lock，否则优先 "},{"t":"code","v":"synchronized"},{"t":"text","v":"。"}]}],"parentId":"thread-详细说说synchronized"},{"id":"thread-详细说说synchronized-为什么多线程-i++-可能出奇怪结果","module":"thread","title":"为什么多线程 i++ 可能出奇怪结果","level":"extra","summary":"i++ 在字节码里大致是读静态变量、压常量 1、相加、再写回，不是一条原子指令。多线…","blocks":[{"type":"p","inlines":[{"t":"code","v":"i++"},{"t":"text","v":" 在字节码里大致是读静态变量、压常量 1、相加、再写回，不是一条原子指令。多线程无锁交错执行时，可能读到旧值、写丢更新，极端交错下计数会错乱。要计数用 "},{"t":"code","v":"AtomicInteger"},{"t":"text","v":" 或把 "},{"t":"code","v":"i++"},{"t":"text","v":" 放进同步块。"}]}],"parentId":"thread-详细说说synchronized"},{"id":"thread-详细说说ReentrantLock","module":"thread","title":"详细说说ReentrantLock","level":"core","summary":"ReentrantLock 是 java.util.concurrent.locks…","blocks":[{"type":"p","inlines":[{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 是 "},{"t":"code","v":"java.util.concurrent.locks"},{"t":"text","v":" 里的可重入互斥锁，实现了 "},{"t":"code","v":"Lock"},{"t":"text","v":" 接口。同一时刻只有一个线程能拿到锁；同一个线程可以反复 "},{"t":"code","v":"lock"},{"t":"text","v":"，内部用计数记重入次数，必须配对 "},{"t":"code","v":"unlock"},{"t":"text","v":" 才能真正放开。它不是关键字，不会自动释放，一定要放在 "},{"t":"code","v":"try / finally"},{"t":"text","v":" 里，防止异常把锁带走。"}]},{"type":"p","inlines":[{"t":"text","v":"底层靠 AQS。AQS 里有一个 "},{"t":"code","v":"int state"},{"t":"text","v":" 表示锁状态：0 是没人持有，大于 0 是被持有，数值就是重入次数。还记着当前持有线程。抢不到的线程会进双向等待队列，调用 "},{"t":"code","v":"park"},{"t":"text","v":" 挂起；解锁时把后继 "},{"t":"code","v":"unpark"},{"t":"text","v":" 叫醒。加锁、解锁本身带内存语义：解锁 happens-before 下一次加锁，临界区里的写入下一个拿到锁的线程一定能看见。"}]},{"type":"p","inlines":[{"t":"text","v":"加锁过程可以这么背。"},{"t":"code","v":"lock()"},{"t":"text","v":" 先尝试 CAS 把 "},{"t":"code","v":"state"},{"t":"text","v":" 从 0 改成 1，成功就把自己记成持有者。失败则看是不是自己已经持有：是就 "},{"t":"code","v":"state++"},{"t":"text","v":"，这就是可重入。都不是，就进队列排队，阻塞等唤醒，醒了再抢。"}]},{"type":"p","inlines":[{"t":"text","v":"解锁是 "},{"t":"code","v":"unlock()"},{"t":"text","v":"：必须是持有者，"},{"t":"code","v":"state--"},{"t":"text","v":"。减到 0 才真正释放，清空持有者，唤醒队列里下一个。减错了、不是持有者去 unlock，会抛 "},{"t":"code","v":"IllegalMonitorStateException"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"默认是非公平锁。新来的线程可以插队，队列里有人等着也能先 CAS 一把，成功率高、吞吐好，可能让排队线程饿一段时间。构造时传 "},{"t":"code","v":"true"},{"t":"text","v":" 变成公平锁：先看队列有没有人，有人就老老实实排，先来先得，公平但吞吐差一些。注意：非公平主要体现在加锁阶段可以插队；一旦进了 AQS 队列，唤醒后仍是队头优先，并不是唤醒阶段也随便插。面试默认说非公平，除非业务明确要公平。"}]},{"type":"p","inlines":[{"t":"text","v":"比 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 多几手。"},{"t":"code","v":"tryLock()"},{"t":"text","v":" 试一下，拿不到立刻返回 false，不阻塞，还可以带超时。"},{"t":"code","v":"lockInterruptibly()"},{"t":"text","v":" 等待时可被中断，响应 "},{"t":"code","v":"interrupt"},{"t":"text","v":"。一把锁可以 "},{"t":"code","v":"newCondition()"},{"t":"text","v":" 出多个条件队列，生产者等「不满」、消费者等「不空」，各叫各的，不用 "},{"t":"code","v":"notifyAll"},{"t":"text","v":" 叫醒一堆再筛。这些能力 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 没有，一般场景仍优先关键字：自动释放、JVM 优化多、代码短。"}]}]},{"id":"thread-详细说说ReentrantLock-AQS-是什么，ReentrantLock-怎么用它","module":"thread","title":"AQS 是什么，ReentrantLock 怎么用它","level":"extra","summary":"AQS 是 AbstractQueuedSynchronizer，JUC 锁和同步器…","blocks":[{"type":"p","inlines":[{"t":"text","v":"AQS 是 AbstractQueuedSynchronizer，JUC 锁和同步器的骨架。核心三件："},{"t":"code","v":"state"},{"t":"text","v":"、持有线程、CLH 风格等待队列。子类实现 "},{"t":"code","v":"tryAcquire"},{"t":"text","v":" / "},{"t":"code","v":"tryRelease"},{"t":"text","v":" 这套模板，排队、挂起、唤醒 AQS 包了。"},{"t":"code","v":"CountDownLatch"},{"t":"text","v":"、"},{"t":"code","v":"Semaphore"},{"t":"text","v":"、"},{"t":"code","v":"ReentrantReadWriteLock"},{"t":"text","v":" 也是 AQS，只是对 "},{"t":"code","v":"state"},{"t":"text","v":" 的解释不同。"}]},{"type":"p","inlines":[{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 里面有个内部类 "},{"t":"code","v":"Sync extends AbstractQueuedSynchronizer"},{"t":"text","v":"，真正干活的是它。外面调 "},{"t":"code","v":"lock()"},{"t":"text","v":" / "},{"t":"code","v":"unlock()"},{"t":"text","v":"，最后都进到 Sync。"}]},{"type":"code","text":"// ReentrantLock 简化结构\npublic class ReentrantLock {\n    private final Sync sync;\n    abstract static class Sync extends AbstractQueuedSynchronizer { ... }\n    static final class NonfairSync extends Sync { ... }  // 默认\n    static final class FairSync extends Sync { ... }\n\n    public void lock() { sync.lock(); }\n    public void unlock() { sync.release(1); }\n}"},{"type":"p","inlines":[{"t":"text","v":"AQS 模板方法大致是这样：先让子类试一把，失败再排队。"}]},{"type":"code","text":"// AQS 独占获取（简化）\npublic final void acquire(int arg) {\n    if (!tryAcquire(arg) &&          // 1. 子类：能不能拿到\n        acquireQueued(addWaiter(...), arg)) // 2. 进队 + park 挂起\n        selfInterrupt();\n}\n\npublic final boolean release(int arg) {\n    if (tryRelease(arg)) {           // 1. 子类：能不能释放\n        // 2. unpark 队列后继\n        return true;\n    }\n    return false;\n}"},{"type":"p","inlines":[{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 非公平的 "},{"t":"code","v":"tryAcquire"},{"t":"text","v":" 可以这么背："}]},{"type":"code","text":"// NonfairSync 抢锁（简化）\nprotected final boolean tryAcquire(int acquires) {\n    Thread current = Thread.currentThread();\n    int c = getState();\n    if (c == 0) {                              // 没人持有\n        if (compareAndSetState(0, acquires)) { // CAS：0 → 1\n            setExclusiveOwnerThread(current);  // 记下持有者\n            return true;\n        }\n    } else if (current == getExclusiveOwnerThread()) { // 是自己\n        setState(c + acquires);                // 重入：state++\n        return true;\n    }\n    return false;                              // 别人持有 → 去排队\n}"},{"type":"p","inlines":[{"t":"text","v":"释放对称："}]},{"type":"code","text":"// Sync 放锁（简化）\nprotected final boolean tryRelease(int releases) {\n    int c = getState() - releases;             // state--\n    if (Thread.currentThread() != getExclusiveOwnerThread())\n        throw new IllegalMonitorStateException(); // 不是持有者\n    boolean free = false;\n    if (c == 0) {                              // 重入减完了\n        free = true;\n        setExclusiveOwnerThread(null);         // 清空持有者\n    }\n    setState(c);\n    return free;                               // true → AQS 去唤醒后继\n}"},{"type":"p","inlines":[{"t":"text","v":"串起来："},{"t":"code","v":"lock()"},{"t":"text","v":" → "},{"t":"code","v":"acquire(1)"},{"t":"text","v":" → "},{"t":"code","v":"tryAcquire"},{"t":"text","v":"（CAS 或重入）→ 失败进 AQS 队列 "},{"t":"code","v":"park"},{"t":"text","v":"；"},{"t":"code","v":"unlock()"},{"t":"text","v":" → "},{"t":"code","v":"release(1)"},{"t":"text","v":" → "},{"t":"code","v":"tryRelease"},{"t":"text","v":"（state--）→ 减到 0 就 "},{"t":"code","v":"unpark"},{"t":"text","v":" 下一个。面试就背「模板在 AQS，抢锁逻辑在 Sync」。"}]}],"parentId":"thread-详细说说ReentrantLock"},{"id":"thread-详细说说ReentrantLock-公平锁和不公平锁有什么区别","module":"thread","title":"公平锁和不公平锁有什么区别","level":"extra","summary":"公平：获取前先看队列，前面有人就排队，避免插队，可能饿得少，吞吐低。非公平：上来先 …","blocks":[{"type":"p","inlines":[{"t":"text","v":"公平：获取前先看队列，前面有人就排队，避免插队，可能饿得少，吞吐低。非公平：上来先 CAS 抢，抢不到再排队；刚释放锁时，正在跑的线程可能比被唤醒的线程更快抢到，减少线程切换。"},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 默认非公平。公平、非公平都可重入，可重入跟公不公平无关。"}]}],"parentId":"thread-详细说说ReentrantLock"},{"id":"thread-详细说说ReentrantLock-tryLock-和-lock-有什么区别","module":"thread","title":"tryLock 和 lock 有什么区别","level":"extra","summary":"lock() 拿不到就一直等，默认还不响应中断（中断标记会记下，等拿到锁再处理）。t…","blocks":[{"type":"p","inlines":[{"t":"code","v":"lock()"},{"t":"text","v":" 拿不到就一直等，默认还不响应中断（中断标记会记下，等拿到锁再处理）。"},{"t":"code","v":"tryLock()"},{"t":"text","v":" 立刻试一次，失败返回 false，线程继续干别的。带时间的 "},{"t":"code","v":"tryLock(timeout, unit)"},{"t":"text","v":" 等到点或被中断就返回。需要「锁可选、别卡死」用 tryLock；必须进临界区再用 lock。"}]}],"parentId":"thread-详细说说ReentrantLock"},{"id":"thread-详细说说ReentrantLock-lockInterruptibly-是干什么的","module":"thread","title":"lockInterruptibly 是干什么的","level":"extra","summary":"等待锁的过程中如果被 interrupt，会抛 InterruptedExcepti…","blocks":[{"type":"p","inlines":[{"t":"text","v":"等待锁的过程中如果被 "},{"t":"code","v":"interrupt"},{"t":"text","v":"，会抛 "},{"t":"code","v":"InterruptedException"},{"t":"text","v":" 并放弃等待。适合取消任务、超时停服务这类场景。普通 "},{"t":"code","v":"lock()"},{"t":"text","v":" 排队时不抛中断异常。能响应中断是相对 "},{"t":"code","v":"synchronized"},{"t":"text","v":" 的一个加分点："},{"t":"code","v":"synchronized"},{"t":"text","v":" 阻塞在 monitor 上时中断只是打个标记，不会把你从锁等待里拽出来。"}]}],"parentId":"thread-详细说说ReentrantLock"},{"id":"thread-详细说说ReentrantLock-Condition-和-wait、notify-有什么区别","module":"thread","title":"Condition 和 wait、notify 有什么区别","level":"extra","summary":"都是「等条件、条件满足再醒」。wait / notify 绑在对象监视器上，一把锁只…","blocks":[{"type":"p","inlines":[{"t":"text","v":"都是「等条件、条件满足再醒」。"},{"t":"code","v":"wait"},{"t":"text","v":" / "},{"t":"code","v":"notify"},{"t":"text","v":" 绑在对象监视器上，一把锁只有一个等待集，只能 "},{"t":"code","v":"notify"},{"t":"text","v":" 或 "},{"t":"code","v":"notifyAll"},{"t":"text","v":"。"},{"t":"code","v":"Condition"},{"t":"text","v":" 从 "},{"t":"code","v":"Lock"},{"t":"text","v":" 上 new 出来，一把 "},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 可以多个 Condition，精确唤醒。调用 "},{"t":"code","v":"await"},{"t":"text","v":" 前必须持有锁，await 会释放锁；"},{"t":"code","v":"signal"},{"t":"text","v":" / "},{"t":"code","v":"signalAll"},{"t":"text","v":" 也要持有同一把锁。用完一样要 finally unlock。生产者消费者优先 Condition，少假死、少无意义唤醒。"}]}],"parentId":"thread-详细说说ReentrantLock"},{"id":"thread-详细说说ReentrantLock-为什么必须在-finally-里-unlock","module":"thread","title":"为什么必须在 finally 里 unlock","level":"extra","summary":"synchronized 出代码块 JVM 会保证 monitorexit。Reen…","blocks":[{"type":"p","inlines":[{"t":"code","v":"synchronized"},{"t":"text","v":" 出代码块 JVM 会保证 monitorexit。"},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 是普通方法调用，异常、return 都可能跳过 "},{"t":"code","v":"unlock"},{"t":"text","v":"，锁就再也放不掉，别的线程全堵死。标准写法是 lock 之后立刻 try，业务放 try 里，unlock 只放 finally。不要 lock 成功才 try 这种写法写丢了。"}]}],"parentId":"thread-详细说说ReentrantLock"},{"id":"thread-详细说说ThreadLocal","module":"thread","title":"详细说说ThreadLocal","level":"core","summary":"ThreadLocal 让每个线程有一份自己的变量副本，线程之间互不干扰。它解决的不…","blocks":[{"type":"p","inlines":[{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 让每个线程有一份自己的变量副本，线程之间互不干扰。它解决的不是共享，而是隔离：不用加锁，也能在同一线程的调用链里传递上下文，比如用户信息、事务连接、traceId。"}]},{"type":"p","inlines":[{"t":"text","v":"用法就三板斧："},{"t":"code","v":"set"},{"t":"text","v":" 放值，"},{"t":"code","v":"get"},{"t":"text","v":" 取值，用完 "},{"t":"code","v":"remove"},{"t":"text","v":"。第一次 "},{"t":"code","v":"get"},{"t":"text","v":" 时如果没 set，会走 "},{"t":"code","v":"initialValue"},{"t":"text","v":"，默认是 null，也可以重写或用 "},{"t":"code","v":"withInitial"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"底层不在 "},{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 对象里存所有线程的值，而是每个 "},{"t":"code","v":"Thread"},{"t":"text","v":" 里挂一个 "},{"t":"code","v":"ThreadLocalMap"},{"t":"text","v":"。"},{"t":"code","v":"set/get"},{"t":"text","v":" 时用当前 "},{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 当 key，去当前线程的 map 里找 entry。所以「一份 ThreadLocal、多个线程」，实际是「多个线程各有一张表」。"}]},{"type":"p","inlines":[{"t":"code","v":"ThreadLocalMap"},{"t":"text","v":" 的 key 是弱引用："},{"t":"code","v":"Entry extends WeakReference<ThreadLocal<?>>"},{"t":"text","v":"。key 指向的 "},{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 没强引用时，GC 可以把 key 收掉，entry 变成「key 为 null、value 还在」。value 仍被线程的 map 强引用着，线程不结束就不会释放。这就是常说的内存泄漏风险。"}]},{"type":"p","inlines":[{"t":"text","v":"泄漏在线程池里最容易爆。线程被复用，map 一直活着；业务里 "},{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 用完不 "},{"t":"code","v":"remove"},{"t":"text","v":"，下一次任务还能读到脏数据，堆也会慢慢涨。正确做法是：用完一定 "},{"t":"code","v":"remove"},{"t":"text","v":"，最好放在 "},{"t":"code","v":"finally"},{"t":"text","v":" 里。"},{"t":"code","v":"get/set"},{"t":"text","v":" 时也会顺手清理一些 key 为 null 的脏 entry，但不能当规范依赖。"}]},{"type":"p","inlines":[{"t":"text","v":"常见用法：每个请求一个用户上下文；数据库连接、Session 绑在当前线程；SimpleDateFormat 这种非线程安全对象做成线程私有，避免共享加锁。父子线程传值用 "},{"t":"code","v":"InheritableThreadLocal"},{"t":"text","v":"，子线程创建时会拷一份父线程的值；线程池里子线程早创建好了，普通 Inheritable 传不过去，要用阿里 TransmittableThreadLocal 这类方案。"}]}]},{"id":"thread-详细说说ThreadLocal-ThreadLocal-为什么会出现内存泄漏","module":"thread","title":"ThreadLocal 为什么会出现内存泄漏","level":"extra","summary":"key 是弱引用，value 是强引用。ThreadLocal 对象本身没人引用后，…","blocks":[{"type":"p","inlines":[{"t":"text","v":"key 是弱引用，value 是强引用。"},{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 对象本身没人引用后，key 被回收，entry 变成 "},{"t":"code","v":"null -> 大对象"},{"t":"text","v":"。线程（尤其是池里的线程）还活着，map 就一直握着 value。所以不是「弱引用导致泄漏」，而是「弱引用清了 key，value 没人清」。"}]}],"parentId":"thread-详细说说ThreadLocal"},{"id":"thread-详细说说ThreadLocal-为什么-key-要用弱引用","module":"thread","title":"为什么 key 要用弱引用","level":"extra","summary":"如果 key 也是强引用，即使业务代码里 ThreadLocal 静态变量都没了，只…","blocks":[{"type":"p","inlines":[{"t":"text","v":"如果 key 也是强引用，即使业务代码里 ThreadLocal 静态变量都没了，只要线程还在，map 就会一直强引用着 ThreadLocal，类都卸不掉。弱引用让 ThreadLocal 本身能被回收，再配合 "},{"t":"code","v":"remove"},{"t":"text","v":" 和启发式清理脏 entry。设计假设是：你用完会 "},{"t":"code","v":"remove"},{"t":"text","v":"。"}]}],"parentId":"thread-详细说说ThreadLocal"},{"id":"thread-详细说说ThreadLocal-和-synchronized-有什么区别","module":"thread","title":"和 synchronized 有什么区别","level":"extra","summary":"synchronized 是多线程抢同一份数据，靠互斥保证安全。ThreadLoca…","blocks":[{"type":"p","inlines":[{"t":"code","v":"synchronized"},{"t":"text","v":" 是多线程抢同一份数据，靠互斥保证安全。"},{"t":"code","v":"ThreadLocal"},{"t":"text","v":" 是每线程一份，根本不共享，所以不用锁。一个解决共享冲突，一个避免共享。能隔离就别硬共享加锁。"}]}],"parentId":"thread-详细说说ThreadLocal"},{"id":"thread-详细说说阻塞队列","module":"thread","title":"详细说说阻塞队列","level":"core","summary":"阻塞队列是 线程安全的队列，在空/满时不是立刻失败，而是让线程 阻塞等待（也可选超时…","blocks":[{"type":"p","inlines":[{"t":"text","v":"阻塞队列是 线程安全的队列，在空/满时不是立刻失败，而是让线程 阻塞等待（也可选超时、非阻塞）。JUC 里根接口是 "},{"t":"code","v":"BlockingQueue"},{"t":"text","v":"，生产者-消费者、线程池工作队列都靠它。"}]},{"type":"p","inlines":[{"t":"text","v":"核心语义一句话：空了 take/poll 可阻塞；满了 put/offer 可阻塞；多线程同时操作安全。"}]},{"type":"p","inlines":[{"t":"text","v":"和普通队列差在哪"}]},{"type":"p","inlines":[{"t":"text","v":"| | 普通队列（如非并发的） | 阻塞队列 |"}]},{"type":"p","inlines":[{"t":"text","v":"|--|------------------------|----------|"}]},{"type":"p","inlines":[{"t":"text","v":"| 空时取 | 往往返回 null / 抛异常 | 可一直等有元素 |"}]},{"type":"p","inlines":[{"t":"text","v":"| 满时放 | 往往失败 / 抛异常 | 可一直等有空位 |"}]},{"type":"p","inlines":[{"t":"text","v":"| 并发 | 自己加锁 | 实现类内部已同步 |"}]},{"type":"p","inlines":[{"t":"text","v":"四组操作（必背）"}]},{"type":"p","inlines":[{"t":"text","v":"以「放」和「取」各四种策略记："}]},{"type":"p","inlines":[{"t":"text","v":"| | 抛异常 | 特殊值 | 阻塞 | 超时 |"}]},{"type":"p","inlines":[{"t":"text","v":"|--|--------|--------|------|------|"}]},{"type":"p","inlines":[{"t":"text","v":"| 入队 | "},{"t":"code","v":"add(e)"},{"t":"text","v":" | "},{"t":"code","v":"offer(e)"},{"t":"text","v":" → false | "},{"t":"code","v":"put(e)"},{"t":"text","v":" | "},{"t":"code","v":"offer(e, time, unit)"},{"t":"text","v":" |"}]},{"type":"p","inlines":[{"t":"text","v":"| 出队 | "},{"t":"code","v":"remove()"},{"t":"text","v":" | "},{"t":"code","v":"poll()"},{"t":"text","v":" → null | "},{"t":"code","v":"take()"},{"t":"text","v":" | "},{"t":"code","v":"poll(time, unit)"},{"t":"text","v":" |"}]},{"type":"p","inlines":[{"t":"text","v":"| 查看队头 | "},{"t":"code","v":"element()"},{"t":"text","v":" | "},{"t":"code","v":"peek()"},{"t":"text","v":" → null | — | — |"}]},{"type":"p","inlines":[{"t":"text","v":"面试常考：线程池、生产者消费者里用 "},{"t":"code","v":"put"},{"t":"text","v":" / "},{"t":"code","v":"take"},{"t":"text","v":"（阻塞）还是 "},{"t":"code","v":"offer"},{"t":"text","v":" / "},{"t":"code","v":"poll"},{"t":"text","v":"（带超时/立刻返回），看能不能接受一直堵。"}]},{"type":"p","inlines":[{"t":"text","v":"常见实现类"}]},{"type":"p","inlines":[{"t":"code","v":"ArrayBlockingQueue"}]},{"type":"p","inlines":[{"t":"text","v":"数组有界。构造时定容量，一把锁 + 两个条件（非空/非满）。吞吐一般，边界清晰，适合明确限流缓冲。"}]},{"type":"p","inlines":[{"t":"code","v":"LinkedBlockingQueue"}]},{"type":"p","inlines":[{"t":"text","v":"链表，可选有界（默认 "},{"t":"code","v":"Integer.MAX_VALUE"},{"t":"text","v":" 近似无界）。两把锁（放一把、取一把），吞吐往往更好。线程池里若不设界，队列可能涨到撑爆内存——生产要设容量。"}]},{"type":"p","inlines":[{"t":"code","v":"SynchronousQueue"}]},{"type":"p","inlines":[{"t":"text","v":"容量 0：一次 "},{"t":"code","v":"put"},{"t":"text","v":" 必须等另一个线程 "},{"t":"code","v":"take"},{"t":"text","v":"，不存元素。"},{"t":"code","v":"Executors.newCachedThreadPool"},{"t":"text","v":" 用它：有空闲线程就交接任务，没有就新建。"}]},{"type":"p","inlines":[{"t":"code","v":"PriorityBlockingQueue"}]},{"type":"p","inlines":[{"t":"text","v":"无界，按优先级出队（元素要 "},{"t":"code","v":"Comparable"},{"t":"text","v":" 或提供比较器）。无「满」阻塞，只有取的时候可能空等。"}]},{"type":"p","inlines":[{"t":"code","v":"DelayQueue"}]},{"type":"p","inlines":[{"t":"text","v":"元素实现 "},{"t":"code","v":"Delayed"},{"t":"text","v":"，到期才能被取出。适合延迟任务、超时订单扫描。"}]},{"type":"p","inlines":[{"t":"code","v":"LinkedTransferQueue"}]},{"type":"p","inlines":[{"t":"text","v":"更强的传递语义（"},{"t":"code","v":"transfer"},{"t":"text","v":"：把元素直接交给消费者），高并发传递场景。"}]},{"type":"code","text":"flowchart LR\n  P[生产者] -->|put / offer| Q[BlockingQueue]\n  Q -->|take / poll| C[消费者]"},{"type":"p","inlines":[{"t":"text","v":"底层怎么阻塞（口述）"}]},{"type":"p","inlines":[{"t":"text","v":"多数有界实现类似："},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" + 两个 "},{"t":"code","v":"Condition"},{"t":"text","v":"（"},{"t":"code","v":"notEmpty"},{"t":"text","v":" / "},{"t":"code","v":"notFull"},{"t":"text","v":"）。"}]},{"type":"p","inlines":[{"t":"text","v":"满了 "},{"t":"code","v":"put"},{"t":"text","v":" → "},{"t":"code","v":"await"},{"t":"text","v":" 在 "},{"t":"code","v":"notFull"},{"t":"text","v":"；有人 "},{"t":"code","v":"take"},{"t":"text","v":" 拿走 → "},{"t":"code","v":"signal"},{"t":"text","v":" 不满。"}]},{"type":"p","inlines":[{"t":"text","v":"空了 "},{"t":"code","v":"take"},{"t":"text","v":" → "},{"t":"code","v":"await"},{"t":"text","v":" 在 "},{"t":"code","v":"notEmpty"},{"t":"text","v":"；有人 "},{"t":"code","v":"put"},{"t":"text","v":" → "},{"t":"code","v":"signal"},{"t":"text","v":" 不空。"}]},{"type":"p","inlines":[{"t":"text","v":"和「自己用 wait/notify 写生产者消费者」是同一套思想，API 封装好了。"}]},{"type":"p","inlines":[{"t":"text","v":"和线程池的关系"}]},{"type":"p","inlines":[{"t":"code","v":"ThreadPoolExecutor"},{"t":"text","v":" 的第三个参数就是工作队列。常见搭配："}]},{"type":"li","inlines":[{"t":"text","v":"固定大小池 + "},{"t":"code","v":"ArrayBlockingQueue"},{"t":"text","v":"：队列有界，拒绝策略好控。"}]},{"type":"li","inlines":[{"t":"text","v":"默认 "},{"t":"code","v":"LinkedBlockingQueue"},{"t":"text","v":" 无界（如 "},{"t":"code","v":"newFixedThreadPool"},{"t":"text","v":"）：任务可能堆积 OOM。"}]},{"type":"li","inlines":[{"t":"code","v":"SynchronousQueue"},{"t":"text","v":"：不排队，直接交接或开新线程（cached 池）。"}]},{"type":"p","inlines":[{"t":"text","v":"背一句：队列选型决定缓冲多深、会不会把内存吃光、拒绝策略何时触发。"}]}]},{"id":"thread-详细说说阻塞队列-puttake-和-offerpoll-怎么选","module":"thread","title":"put/take 和 offer/poll 怎么选","level":"extra","summary":"需要背压、宁可慢也要等 → put/take。","blocks":[{"type":"p","inlines":[{"t":"text","v":"需要背压、宁可慢也要等 → "},{"t":"code","v":"put"},{"t":"text","v":"/"},{"t":"code","v":"take"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"不能无限等、要快速失败或超时 → "},{"t":"code","v":"offer"},{"t":"text","v":"/"},{"t":"code","v":"poll"},{"t":"text","v":"（可带超时）。线程池提交任务常用 "},{"t":"code","v":"offer"},{"t":"text","v":"，失败再走拒绝策略。"}]}],"parentId":"thread-详细说说阻塞队列"},{"id":"thread-详细说说阻塞队列-ArrayBlockingQueue-和-LinkedBlockingQueue-怎么选","module":"thread","title":"ArrayBlockingQueue 和 LinkedBlockingQueue 怎么选","level":"extra","summary":"要严格有界、简单限流 → ArrayBlockingQueue。","blocks":[{"type":"p","inlines":[{"t":"text","v":"要严格有界、简单限流 → "},{"t":"code","v":"ArrayBlockingQueue"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"高吞吐、长度可估并设上限 → "},{"t":"code","v":"LinkedBlockingQueue(capacity)"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"千万别在生产用「默认无界」的 Linked 当无限缓冲。"}]}],"parentId":"thread-详细说说阻塞队列"},{"id":"thread-详细说说阻塞队列-为什么说-SynchronousQueue-不存元素","module":"thread","title":"为什么说 SynchronousQueue 不存元素","level":"extra","summary":"容量是 0，put 阻塞到有线程 take（或反过来），元素直接在线程间移交。适合「…","blocks":[{"type":"p","inlines":[{"t":"text","v":"容量是 0，"},{"t":"code","v":"put"},{"t":"text","v":" 阻塞到有线程 "},{"t":"code","v":"take"},{"t":"text","v":"（或反过来），元素直接在线程间移交。适合「一手交一手」的传递，不适合做任务堆积缓冲。"}]}],"parentId":"thread-详细说说阻塞队列"},{"id":"thread-说说CopyOnWriteArrayList","module":"thread","title":"说说CopyOnWriteArrayList","level":"core","summary":"CopyOnWriteArrayList 是 JUC 里的 线程安全 List。思路…","blocks":[{"type":"p","inlines":[{"t":"code","v":"CopyOnWriteArrayList"},{"t":"text","v":" 是 JUC 里的 线程安全 List。思路就四个字：写时复制——改数据先拷一份新数组，改完再整体换上；读一直读当前数组，不加锁。"}]},{"type":"p","inlines":[{"t":"text","v":"适合 读多写少：监听器列表、配置快照、黑白名单这类。写一多就又拷数组又占内存，性能会很难看。"}]},{"type":"p","inlines":[{"t":"text","v":"底层怎么干"}]},{"type":"p","inlines":[{"t":"text","v":"内部是一个 "},{"t":"code","v":"volatile Object[] array"},{"t":"text","v":"，外加一把 "},{"t":"code","v":"ReentrantLock"},{"t":"text","v":"（写路径用）。"}]},{"type":"p","inlines":[{"t":"text","v":"读：直接拿 "},{"t":"code","v":"array"},{"t":"text","v":" 下标访问或遍历。不加锁，靠 "},{"t":"code","v":"volatile"},{"t":"text","v":" 保证能看到别人换上去的新数组引用。"}]},{"type":"p","inlines":[{"t":"text","v":"写（"},{"t":"code","v":"add"},{"t":"text","v":" / "},{"t":"code","v":"set"},{"t":"text","v":" / "},{"t":"code","v":"remove"},{"t":"text","v":" 等）大致是："}]},{"type":"li","inlines":[{"t":"code","v":"lock.lock()"}]},{"type":"li","inlines":[{"t":"text","v":"把当前数组 整份拷贝 成新数组（长度可能 +1 / -1）"}]},{"type":"li","inlines":[{"t":"text","v":"在新数组上改"}]},{"type":"li","inlines":[{"t":"code","v":"setArray(新数组)"},{"t":"text","v":" —— 一次 "},{"t":"code","v":"volatile"},{"t":"text","v":" 写，把引用换掉"}]},{"type":"li","inlines":[{"t":"code","v":"unlock"}]},{"type":"p","inlines":[{"t":"text","v":"口述：读无锁；写串行 + 整表拷贝；换数组是原子可见的。"}]},{"type":"code","text":"// add 语义对齐源码，便于背，不是完整实现\npublic boolean add(E e) {\n    final ReentrantLock lock = this.lock;\n    lock.lock();\n    try {\n        Object[] elements = getArray();\n        int len = elements.length;\n        Object[] newElements = Arrays.copyOf(elements, len + 1);\n        newElements[len] = e;\n        setArray(newElements); // volatile 写\n        return true;\n    } finally {\n        lock.unlock();\n    }\n}"},{"type":"p","inlines":[{"t":"text","v":"迭代器是弱一致的"}]},{"type":"p","inlines":[{"t":"code","v":"iterator()"},{"t":"text","v":" 拿到的是 创建迭代器那一刻的数组快照。之后别人怎么 add/remove，这个迭代器都还扫旧数组，不会抛 "},{"t":"code","v":"ConcurrentModificationException"},{"t":"text","v":"，也 看不到 迭代开始后的新写入。"}]},{"type":"p","inlines":[{"t":"text","v":"这叫 弱一致性：安全、不炸，但不保证实时最新。"}]},{"type":"p","inlines":[{"t":"text","v":"和常见「安全 List」怎么比"}]},{"type":"li","inlines":[{"t":"code","v":"Collections.synchronizedList"},{"t":"text","v":" / "},{"t":"code","v":"Vector"},{"t":"text","v":"：读写都抢同一把锁，读也被写堵住；迭代还要自己额外同步，否则仍可能 CME。"}]},{"type":"li","inlines":[{"t":"code","v":"CopyOnWriteArrayList"},{"t":"text","v":"：读基本不堵写；写贵（拷贝）；迭代用快照，天然不 CME。"}]},{"type":"li","inlines":[{"t":"code","v":"ConcurrentHashMap"},{"t":"text","v":"：是 Map，桶级并发写；COW 是 List，写时整数组复制，定位场景不同。"}]},{"type":"p","inlines":[{"t":"text","v":"优缺点（面试常收尾）"}]},{"type":"p","inlines":[{"t":"text","v":"优点"}]},{"type":"li","inlines":[{"t":"text","v":"读路径极轻，高并发读友好"}]},{"type":"li","inlines":[{"t":"text","v":"迭代简单、无 CME"}]},{"type":"p","inlines":[{"t":"text","v":"缺点"}]},{"type":"li","inlines":[{"t":"text","v":"每次写都拷数组：写多、元素多时 CPU + 内存压力大"}]},{"type":"li","inlines":[{"t":"text","v":"读到的可能是旧快照，不适合强一致实时数据"}]},{"type":"li","inlines":[{"t":"text","v":"数组里仍可能有重复元素（"},{"t":"code","v":"add"},{"t":"text","v":" 不查重；要唯一用 "},{"t":"code","v":"addIfAbsent"},{"t":"text","v":"）"}]},{"type":"p","inlines":[{"t":"text","v":"一句话选型：读远多于写，且能接受短暂旧数据 → 可以考虑 COW；写频繁或要强一致 → 别用。"}]}]},{"id":"thread-说说CopyOnWriteArrayList-为什么写要加锁，读却不加","module":"thread","title":"为什么写要加锁，读却不加","level":"extra","summary":"写必须串行，否则两个线程各拷一份、再各自 setArray，后写会把先写的改动盖掉。…","blocks":[{"type":"p","inlines":[{"t":"text","v":"写必须串行，否则两个线程各拷一份、再各自 "},{"t":"code","v":"setArray"},{"t":"text","v":"，后写会把先写的改动盖掉。读只读当前 "},{"t":"code","v":"array"},{"t":"text","v":" 引用指向的那份内容，数组本身写完才挂上去，读侧不加锁也不会改坏结构；新数组靠 "},{"t":"code","v":"volatile"},{"t":"text","v":" 发布。"}]}],"parentId":"thread-说说CopyOnWriteArrayList"},{"id":"thread-说说CopyOnWriteArrayList-和-CopyOnWriteArraySet-什么关系","module":"thread","title":"和 CopyOnWriteArraySet 什么关系","level":"extra","summary":"CopyOnWriteArraySet 内部就是包了一个 CopyOnWriteAr…","blocks":[{"type":"p","inlines":[{"t":"code","v":"CopyOnWriteArraySet"},{"t":"text","v":" 内部就是包了一个 "},{"t":"code","v":"CopyOnWriteArrayList"},{"t":"text","v":"，靠 "},{"t":"code","v":"addIfAbsent"},{"t":"text","v":" 保唯一。同样读多写少，集合语义。"}]}],"parentId":"thread-说说CopyOnWriteArrayList"},{"id":"thread-说说CopyOnWriteArrayList-什么场景绝对不该用","module":"thread","title":"什么场景绝对不该用","level":"extra","summary":"订单流水、聊天消息这种 写很勤 的列表；或者业务要求 读必须立刻看到刚写入。这时更合…","blocks":[{"type":"p","inlines":[{"t":"text","v":"订单流水、聊天消息这种 写很勤 的列表；或者业务要求 读必须立刻看到刚写入。这时更合适的是加锁的普通 List、或别的并发结构，而不是每次写都整表拷贝。"}]}],"parentId":"thread-说说CopyOnWriteArrayList"},{"id":"thread-说说CopyOnWriteArrayList-遍历时能边遍历边删吗","module":"thread","title":"遍历时能边遍历边删吗","level":"extra","summary":"迭代器是快照，Iterator.remove() 不支持（会抛 Unsupporte…","blocks":[{"type":"p","inlines":[{"t":"text","v":"迭代器是快照，"},{"t":"code","v":"Iterator.remove()"},{"t":"text","v":" 不支持（会抛 "},{"t":"code","v":"UnsupportedOperationException"},{"t":"text","v":"）。要删用容器自己的 "},{"t":"code","v":"remove"},{"t":"text","v":" / "},{"t":"code","v":"removeIf"},{"t":"text","v":"，那是写路径，会再拷一份新数组。遍历过程中别人删了，你这个迭代器仍扫旧快照，互不影响。"}]}],"parentId":"thread-说说CopyOnWriteArrayList"},{"id":"thread-什么是As-if-Serial语义","module":"thread","title":"什么是As-if-Serial语义","level":"core","summary":"As-if-Serial 的意思是：不管编译器、处理器怎么重排序，单线程程序的执行结…","blocks":[{"type":"p","inlines":[{"t":"text","v":"As-if-Serial 的意思是：不管编译器、处理器怎么重排序，单线程程序的执行结果不能被改变，看起来就像按代码书写顺序执行一样。"}]},{"type":"p","inlines":[{"t":"text","v":"为什么要重排：编译器和 CPU 为了并行、流水线，会把没有依赖的指令挪位置。能挪，但不能把结果改坏。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么守住：有数据依赖的操作不能乱排。比如先 "},{"t":"code","v":"a = 1"},{"t":"text","v":"，再 "},{"t":"code","v":"b = a"},{"t":"text","v":"，这两步不能对调，否则结果错了。没有依赖的，比如 "},{"t":"code","v":"a = 1"},{"t":"text","v":" 和 "},{"t":"code","v":"b = 2"},{"t":"text","v":"，可以重排，单线程结果一样。"}]},{"type":"p","inlines":[{"t":"text","v":"边界要讲清：As-if-Serial 只管单线程。多核、多线程各有各的执行序列，跨线程谁先写、谁先读，单靠它保不住可见性。多线程还要靠 happens-before、"},{"t":"code","v":"volatile"},{"t":"text","v":"、锁。"}]},{"type":"p","inlines":[{"t":"text","v":"和 happens-before 的关系：单线程里，程序次序规则和 As-if-Serial 是对齐的；跨线程必须另有锁、"},{"t":"code","v":"volatile"},{"t":"text","v":"、"},{"t":"code","v":"start"},{"t":"text","v":"/"},{"t":"code","v":"join"},{"t":"text","v":" 这些规则，才能保证「我写完你一定看见」。"}]}]},{"id":"thread-什么是As-if-Serial语义-有控制依赖就能随便重排吗","module":"thread","title":"有控制依赖就能随便重排吗","level":"extra","summary":"控制依赖是「要不要执行」的依赖，比如 if (flag) { ... }。编译器、处…","blocks":[{"type":"p","inlines":[{"t":"text","v":"控制依赖是「要不要执行」的依赖，比如 "},{"t":"code","v":"if (flag) { ... }"},{"t":"text","v":"。编译器、处理器有时仍可能重排，单线程结果仍要符合 As-if-Serial。多线程里靠控制依赖挡重排不可靠，需要内存屏障或同步原语。"}]}],"parentId":"thread-什么是As-if-Serial语义"},{"id":"thread-什么是As-if-Serial语义-和指令重排是什么关系","module":"thread","title":"和指令重排是什么关系","level":"extra","summary":"指令重排是手段，As-if-Serial 是约束：可以重排，但单线程结果必须等价。面…","blocks":[{"type":"p","inlines":[{"t":"text","v":"指令重排是手段，As-if-Serial 是约束：可以重排，但单线程结果必须等价。面试可以说「允许重排，但不允许改变单线程语义」。"}]}],"parentId":"thread-什么是As-if-Serial语义"},{"id":"thread-写个DCL单例为什么要volatile","module":"thread","title":"写个DCL单例为什么要volatile","level":"core","summary":"DCL 是双重检查锁定（Double-Checked Locking）：先不加锁看一…","blocks":[{"type":"p","inlines":[{"t":"text","v":"DCL 是双重检查锁定（Double-Checked Locking）：先不加锁看一眼实例是不是 null，是 null 再进同步块，进了再判一次，避免每次 get 都抢锁。经典写法是实例字段加 "},{"t":"code","v":"volatile"},{"t":"text","v":"。"}]},{"type":"code","text":"public class Singleton {\n    private static volatile Singleton instance;\n\n    private Singleton() {}\n\n    public static Singleton getInstance() {\n        if (instance == null) {                 // 第一次检查，无锁\n            synchronized (Singleton.class) {\n                if (instance == null) {         // 第二次检查，有锁\n                    instance = new Singleton();\n                }\n            }\n        }\n        return instance;\n    }\n}"},{"type":"p","inlines":[{"t":"text","v":"为什么要 "},{"t":"code","v":"volatile"},{"t":"text","v":"：因为 "},{"t":"code","v":"instance = new Singleton()"},{"t":"text","v":" 不是原子操作，大致拆成三步："}]},{"type":"li","inlines":[{"t":"text","v":"分配内存"}]},{"type":"li","inlines":[{"t":"text","v":"调用构造，初始化对象"}]},{"type":"li","inlines":[{"t":"text","v":"把引用赋值给 "},{"t":"code","v":"instance"}]},{"type":"p","inlines":[{"t":"text","v":"没有 "},{"t":"code","v":"volatile"},{"t":"text","v":"，步骤 2 和 3 可能被重排：先赋值引用，再跑构造。线程 A 写完引用还没初始化完，线程 B 第一次检查发现 "},{"t":"code","v":"instance != null"},{"t":"text","v":"，直接拿去用，看到的是半初始化对象，字段还是默认值，后面就炸。"}]},{"type":"p","inlines":[{"t":"code","v":"volatile"},{"t":"text","v":" 挡住这步重排，并保证写对后续读可见：发布出去的一定是构造完的对象。这就是「安全发布」。"}]},{"type":"p","inlines":[{"t":"text","v":"没有 DCL 也可以：静态内部类持有实例、枚举单例，靠类加载保证线程安全，面试常说这几种更省心。如果硬写懒汉 DCL，实例必须 "},{"t":"code","v":"volatile"},{"t":"text","v":"。"}]}]},{"id":"thread-写个DCL单例为什么要volatile-只有-synchronized-不够吗","module":"thread","title":"只有 synchronized 不够吗","level":"extra","summary":"第二次检查在锁里，互斥没问题，但出锁之后别的线程靠第一次检查读 instance，读…","blocks":[{"type":"p","inlines":[{"t":"text","v":"第二次检查在锁里，互斥没问题，但出锁之后别的线程靠第一次检查读 "},{"t":"code","v":"instance"},{"t":"text","v":"，读的是普通字段。没有 "},{"t":"code","v":"volatile"},{"t":"text","v":"，既可能看到重排后的半成品，也可能缓存里还是旧的 null（可见性）。锁只保证「进过同步块的线程」之间的可见；第一次检查根本没进锁。"}]}],"parentId":"thread-写个DCL单例为什么要volatile"},{"id":"thread-写个DCL单例为什么要volatile-new-为什么说不是原子的","module":"thread","title":"new 为什么说不是原子的","level":"extra","summary":"字节码层面大致是 new 分配、invokespecial 调构造、putstati…","blocks":[{"type":"p","inlines":[{"t":"text","v":"字节码层面大致是 "},{"t":"code","v":"new"},{"t":"text","v":" 分配、"},{"t":"code","v":"invokespecial"},{"t":"text","v":" 调构造、"},{"t":"code","v":"putstatic"},{"t":"text","v":"/"},{"t":"code","v":"putfield"},{"t":"text","v":" 写引用，三步可被编译器、CPU 重排。所以「引用非空」不等于「对象已初始化完」。"}]}],"parentId":"thread-写个DCL单例为什么要volatile"},{"id":"thread-写个DCL单例为什么要volatile-和饿汉、静态内部类怎么比","module":"thread","title":"和饿汉、静态内部类怎么比","level":"extra","summary":"饿汉类加载就创建，简单无并发问题，可能浪费。静态内部类：调 getInstance …","blocks":[{"type":"p","inlines":[{"t":"text","v":"饿汉类加载就创建，简单无并发问题，可能浪费。静态内部类：调 "},{"t":"code","v":"getInstance"},{"t":"text","v":" 才加载内部类，既懒又靠类初始化锁保证安全。DCL 是手动懒加载，必须记 "},{"t":"code","v":"volatile"},{"t":"text","v":"。"}]}],"parentId":"thread-写个DCL单例为什么要volatile"},{"id":"thread-什么是MESI","module":"thread","title":"什么是MESI","level":"core","summary":"MESI 是多核 CPU 常用的缓存一致性协议，名字来自缓存行四种状态：Modifi…","blocks":[{"type":"p","inlines":[{"t":"text","v":"MESI 是多核 CPU 常用的缓存一致性协议，名字来自缓存行四种状态：Modified、Exclusive、Shared、Invalid。"}]},{"type":"p","inlines":[{"t":"text","v":"M（Modified，已修改）：本核缓存里的数据改过了，和主存不一致；这份数据只在本核有效。写回主存或被别人要走之前，本核是唯一持有者。"}]},{"type":"p","inlines":[{"t":"text","v":"E（Exclusive，独占）：数据和主存一致，且只有本核有这份副本。自己改的话可以直接变成 M，不用先广播。"}]},{"type":"p","inlines":[{"t":"text","v":"S（Shared，共享）：数据和主存一致，但别的核也可能有同样的副本。要写的话，得先让别人的副本失效。"}]},{"type":"p","inlines":[{"t":"text","v":"I（Invalid，无效）：这行缓存作废了，要用得重新从别的核或主存加载。"}]},{"type":"p","inlines":[{"t":"text","v":"处理器读写时，按当前状态和操作类型改状态，必要时在核之间发消息（比如「我要写，你们把副本作废」），保证同一地址在各核缓存里不会各改各的、长期对不上。"}]},{"type":"p","inlines":[{"t":"text","v":"和 JMM 的关系：MESI 是硬件层怎么同步 Cache；JMM 是语言规范，规定 Java 线程什么时候必须看见别人的写。"},{"t":"code","v":"volatile"},{"t":"text","v":"、锁最终会落到内存屏障、锁总线/锁缓存行，再触发这类一致性协议。面试别把 MESI 和 JMM 说成一回事。"}]}]},{"id":"thread-什么是MESI-为什么需要缓存一致性","module":"thread","title":"为什么需要缓存一致性","level":"extra","summary":"每个核有自己的 Cache，同一变量可能在多个核里各有一份。没有协议，A 核改了，B…","blocks":[{"type":"p","inlines":[{"t":"text","v":"每个核有自己的 Cache，同一变量可能在多个核里各有一份。没有协议，A 核改了，B 核还读旧值，程序语义就崩了。MESI 就是让「谁改了、谁还有效」有规矩。"}]}],"parentId":"thread-什么是MESI"},{"id":"thread-什么是MESI-和伪共享有什么关系","module":"thread","title":"和伪共享有什么关系","level":"extra","summary":"缓存按「行」同步，一行通常 64 字节。两个无关变量若落在同一行，一个核改其中一个，…","blocks":[{"type":"p","inlines":[{"t":"text","v":"缓存按「行」同步，一行通常 64 字节。两个无关变量若落在同一行，一个核改其中一个，可能让另一核整行失效，互刷缓存，这叫伪共享。和 MESI 状态切换有关，高并发里有时用填充把热点字段隔开。"}]}],"parentId":"thread-什么是MESI"},{"id":"thread-说说AQS","module":"thread","title":"说说AQS","level":"core","summary":"AQS 是 AbstractQueuedSynchronizer，JUC 里锁和同步…","blocks":[{"type":"p","inlines":[{"t":"text","v":"AQS 是 "},{"t":"code","v":"AbstractQueuedSynchronizer"},{"t":"text","v":"，JUC 里锁和同步器的骨架。"},{"t":"code","v":"ReentrantLock"},{"t":"text","v":"、"},{"t":"code","v":"ReentrantReadWriteLock"},{"t":"text","v":"、"},{"t":"code","v":"CountDownLatch"},{"t":"text","v":"、"},{"t":"code","v":"Semaphore"},{"t":"text","v":"、"},{"t":"code","v":"ThreadPoolExecutor"},{"t":"text","v":" 用的一些同步器，底层都靠它。"}]},{"type":"p","inlines":[{"t":"text","v":"核心三件套："}]},{"type":"li","inlines":[{"t":"code","v":"volatile int state"},{"t":"text","v":"：同步状态。含义由子类定——互斥锁里 0 空闲、大于 0 持有次数；信号量里是剩余许可；CountDownLatch 里是剩余计数。"}]},{"type":"li","inlines":[{"t":"text","v":"CLH 风格的双向等待队列：抢不到资源的线程包装成 Node 入队，"},{"t":"code","v":"LockSupport.park"},{"t":"text","v":" 挂起；释放时 "},{"t":"code","v":"unpark"},{"t":"text","v":" 后继。"}]},{"type":"li","inlines":[{"t":"text","v":"模板方法：AQS 管排队、阻塞、唤醒；子类实现 "},{"t":"code","v":"tryAcquire"},{"t":"text","v":" / "},{"t":"code","v":"tryRelease"},{"t":"text","v":"（独占）或 "},{"t":"code","v":"tryAcquireShared"},{"t":"text","v":" / "},{"t":"code","v":"tryReleaseShared"},{"t":"text","v":"（共享），告诉框架「这次能不能拿到 / 放掉」。"}]},{"type":"p","inlines":[{"t":"text","v":"独占和共享：独占同一时刻只有一个线程（锁）；共享可以多个（读锁、信号量、Countdown）。条件队列是另一套："},{"t":"code","v":"ConditionObject"},{"t":"text","v":"，"},{"t":"code","v":"await"},{"t":"text","v":" 时释放锁进条件队列，"},{"t":"code","v":"signal"},{"t":"text","v":" 再挪回同步队列等锁。"}]},{"type":"p","inlines":[{"t":"code","v":"LockSupport.park"},{"t":"text","v":" / "},{"t":"code","v":"unpark"},{"t":"text","v":" 是底层挂起、唤醒手段，比 "},{"t":"code","v":"wait"},{"t":"text","v":"/"},{"t":"code","v":"notify"},{"t":"text","v":" 更底层，不要求先持有监视器锁。"}]},{"type":"p","inlines":[{"t":"text","v":"背诵串：资源用 "},{"t":"code","v":"state"},{"t":"text","v":" 表示 → 子类决定怎么改 "},{"t":"code","v":"state"},{"t":"text","v":" → 失败进 AQS 队列 park → 释放成功 unpark 下一个。"}]}]},{"id":"thread-说说AQS-AQS-和-ReentrantLock-什么关系","module":"thread","title":"AQS 和 ReentrantLock 什么关系","level":"extra","summary":"ReentrantLock 内部 Sync extends AQS，公平、非公平是 …","blocks":[{"type":"p","inlines":[{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 内部 "},{"t":"code","v":"Sync extends AQS"},{"t":"text","v":"，公平、非公平是 Sync 的两个子类。外面 "},{"t":"code","v":"lock"},{"t":"text","v":"/"},{"t":"code","v":"unlock"},{"t":"text","v":" 最终调到 AQS 的 "},{"t":"code","v":"acquire"},{"t":"text","v":"/"},{"t":"code","v":"release"},{"t":"text","v":"，真正「能不能抢到」在 "},{"t":"code","v":"tryAcquire"},{"t":"text","v":"/"},{"t":"code","v":"tryRelease"},{"t":"text","v":" 里用 CAS 改 "},{"t":"code","v":"state"},{"t":"text","v":"，并靠 "},{"t":"code","v":"exclusiveOwnerThread"},{"t":"text","v":" 记持有者、支持重入。"}]}],"parentId":"thread-说说AQS"},{"id":"thread-说说AQS-同步队列和条件队列有什么区别","module":"thread","title":"同步队列和条件队列有什么区别","level":"extra","summary":"同步队列：抢锁失败的线程在这排队，锁释放后按规则唤醒。条件队列：已经持有锁的线程 a…","blocks":[{"type":"p","inlines":[{"t":"text","v":"同步队列：抢锁失败的线程在这排队，锁释放后按规则唤醒。条件队列：已经持有锁的线程 "},{"t":"code","v":"await"},{"t":"text","v":" 等业务条件，会先释放锁；"},{"t":"code","v":"signal"},{"t":"text","v":" 后节点转到同步队列，重新去抢锁。一把锁可以多个 Condition，多个条件队列。"}]}],"parentId":"thread-说说AQS"},{"id":"thread-说说AQS-为什么-state-要-volatile","module":"thread","title":"为什么 state 要 volatile","level":"extra","summary":"多线程同时读改同步状态，必须看得见别人的更新；配合 CAS 做原子修改。没有可见性，…","blocks":[{"type":"p","inlines":[{"t":"text","v":"多线程同时读改同步状态，必须看得见别人的更新；配合 CAS 做原子修改。没有可见性，队列和抢锁逻辑都会乱。"}]}],"parentId":"thread-说说AQS"},{"id":"thread-说说CAS","module":"thread","title":"说说CAS","level":"core","summary":"CAS 是 Compare-And-Swap，比较并交换。一次操作带三个量：","blocks":[{"type":"p","inlines":[{"t":"text","v":"CAS 是 Compare-And-Swap，比较并交换。一次操作带三个量："}]},{"type":"li","inlines":[{"t":"text","v":"V：变量在内存里的地址（要改的那个）"}]},{"type":"li","inlines":[{"t":"text","v":"E：预期旧值"}]},{"type":"li","inlines":[{"t":"text","v":"N：要写成的新值"}]},{"type":"p","inlines":[{"t":"text","v":"流程：读出当前值当 E，算出 N，再原子地比较「内存里现在是不是还是 E」——是就把 N 写进去并成功；不是就失败，通常自旋再读再试。整次比较+写入在硬件上是原子的，中间不会被别的核插进来改同一地址。"}]},{"type":"p","inlines":[{"t":"text","v":"它是乐观锁 / 无锁思路：不先加互斥锁，而是假设没人抢，冲突了再重试。不阻塞线程，并发高时往往比重量级锁轻。Java 里原子类、AQS 改 "},{"t":"code","v":"state"},{"t":"text","v":"、ConcurrentHashMap 不少路径，底层都是 CAS（经 "},{"t":"code","v":"Unsafe"},{"t":"text","v":" / "},{"t":"code","v":"VarHandle"},{"t":"text","v":"）。"}]},{"type":"p","inlines":[{"t":"text","v":"缺点也要会说："}]},{"type":"li","inlines":[{"t":"text","v":"自旋耗 CPU：一直失败就一直空转，竞争极烈时可能不如直接阻塞。"}]},{"type":"li","inlines":[{"t":"text","v":"ABA：值从 A→B→A，CAS 仍认为没变。可用版本号，"},{"t":"code","v":"AtomicStampedReference"},{"t":"text","v":"（reference + stamp）。"}]},{"type":"li","inlines":[{"t":"text","v":"只能管一个变量：要对 i、j 一起加，单次 CAS 不够，要么加锁，要么把多个字段塞进一个对象用 "},{"t":"code","v":"AtomicReference"},{"t":"text","v":"。"}]}]},{"id":"thread-说说CAS-CAS-和-synchronized-怎么选","module":"thread","title":"CAS 和 synchronized 怎么选","level":"extra","summary":"冲突少、临界区就是改一个变量：CAS / 原子类更合适。临界区长、要改一堆状态：锁更…","blocks":[{"type":"p","inlines":[{"t":"text","v":"冲突少、临界区就是改一个变量：CAS / 原子类更合适。临界区长、要改一堆状态：锁更清晰，也避免长时间自旋。面试别说「CAS 一定比锁快」，要看竞争和临界区长度。"}]}],"parentId":"thread-说说CAS"},{"id":"thread-说说CAS-ABA-一定有问题吗","module":"thread","title":"ABA 一定有问题吗","level":"extra","summary":"取决于业务。只关心「现在是不是这个值」，ABA 无所谓；关心「中间有没有被改过」（比…","blocks":[{"type":"p","inlines":[{"t":"text","v":"取决于业务。只关心「现在是不是这个值」，ABA 无所谓；关心「中间有没有被改过」（比如栈顶节点被拿下又装回），就要 stamp 或禁止复用。"}]}],"parentId":"thread-说说CAS"},{"id":"thread-说说CAS-Unsafe-还能直接用吗","module":"thread","title":"Unsafe 还能直接用吗","level":"extra","summary":"业务代码不建议依赖 sun.misc.Unsafe。JDK 9 之后更推荐 VarH…","blocks":[{"type":"p","inlines":[{"t":"text","v":"业务代码不建议依赖 "},{"t":"code","v":"sun.misc.Unsafe"},{"t":"text","v":"。JDK 9 之后更推荐 "},{"t":"code","v":"VarHandle"},{"t":"text","v":"。面试知道原子类内部用 CAS 即可。"}]}],"parentId":"thread-说说CAS"},{"id":"thread-说说Atomic类","module":"thread","title":"说说Atomic类","level":"core","summary":"java.util.concurrent.atomic 包提供一组原子变量类，多线程…","blocks":[{"type":"p","inlines":[{"t":"code","v":"java.util.concurrent.atomic"},{"t":"text","v":" 包提供一组原子变量类，多线程改同一个值时不用自己加锁，底层主要是 CAS + "},{"t":"code","v":"volatile"},{"t":"text","v":" + 本地方法。典型场景：计数器、序号、状态标志。"}]},{"type":"p","inlines":[{"t":"text","v":"常见分类可以这么背："}]},{"type":"li","inlines":[{"t":"text","v":"基本类型："},{"t":"code","v":"AtomicInteger"},{"t":"text","v":"、"},{"t":"code","v":"AtomicLong"},{"t":"text","v":"、"},{"t":"code","v":"AtomicBoolean"}]},{"type":"li","inlines":[{"t":"text","v":"引用："},{"t":"code","v":"AtomicReference"},{"t":"text","v":"；带版本解决 ABA 的 "},{"t":"code","v":"AtomicStampedReference"},{"t":"text","v":"；带 mark 位的 "},{"t":"code","v":"AtomicMarkableReference"}]},{"type":"li","inlines":[{"t":"text","v":"数组："},{"t":"code","v":"AtomicIntegerArray"},{"t":"text","v":"、"},{"t":"code","v":"AtomicLongArray"},{"t":"text","v":"、"},{"t":"code","v":"AtomicReferenceArray"},{"t":"text","v":"（对数组元素做原子更新）"}]},{"type":"li","inlines":[{"t":"text","v":"字段更新器："},{"t":"code","v":"AtomicIntegerFieldUpdater"},{"t":"text","v":" 等，对已有对象的 "},{"t":"code","v":"volatile"},{"t":"text","v":" 字段做原子改，对象不用整颗换成 Atomic 包装"}]},{"type":"li","inlines":[{"t":"text","v":"累加器（JDK 8）："},{"t":"code","v":"LongAdder"},{"t":"text","v":"、"},{"t":"code","v":"DoubleAdder"},{"t":"text","v":"、"},{"t":"code","v":"LongAccumulator"},{"t":"text","v":"、"},{"t":"code","v":"DoubleAccumulator"},{"t":"text","v":"。高并发纯累加时，分段热点，比 "},{"t":"code","v":"AtomicLong"},{"t":"text","v":" 吞吐更好；要精确中间值仍用 Atomic"}]},{"type":"p","inlines":[{"t":"code","v":"AtomicInteger"},{"t":"text","v":" 常见 API："},{"t":"code","v":"get"},{"t":"text","v":"/"},{"t":"code","v":"set"},{"t":"text","v":"、"},{"t":"code","v":"getAndIncrement"},{"t":"text","v":"/"},{"t":"code","v":"incrementAndGet"},{"t":"text","v":"、"},{"t":"code","v":"compareAndSet"},{"t":"text","v":"、"},{"t":"code","v":"getAndUpdate"},{"t":"text","v":"。"},{"t":"code","v":"i++"},{"t":"text","v":" 这种读改写三步，换成 "},{"t":"code","v":"incrementAndGet"},{"t":"text","v":" 就是原子的。"}]},{"type":"p","inlines":[{"t":"text","v":"注意：原子类保证的是对该变量这一次更新的原子性，不是「业务方法整体原子」。要改两个相关字段，还得锁或把两个值放进一个不可变对象再 CAS 引用。"}]}]},{"id":"thread-说说Atomic类-AtomicInteger-和-volatile-int-有什么区别","module":"thread","title":"AtomicInteger 和 volatile int 有什么区别","level":"extra","summary":"volatile int 保证可见、有序，但 count++ 仍是三步，会丢更新。A…","blocks":[{"type":"p","inlines":[{"t":"code","v":"volatile int"},{"t":"text","v":" 保证可见、有序，但 "},{"t":"code","v":"count++"},{"t":"text","v":" 仍是三步，会丢更新。"},{"t":"code","v":"AtomicInteger"},{"t":"text","v":" 的自增用 CAS 循环，直到成功，计数不会丢。"}]}],"parentId":"thread-说说Atomic类"},{"id":"thread-说说Atomic类-什么时候用-LongAdder-而不是-AtomicLong","module":"thread","title":"什么时候用 LongAdder 而不是 AtomicLong","level":"extra","summary":"统计 QPS、热点计数这种写特别多、不太读中间精确值的场景，优先 LongAdder…","blocks":[{"type":"p","inlines":[{"t":"text","v":"统计 QPS、热点计数这种写特别多、不太读中间精确值的场景，优先 "},{"t":"code","v":"LongAdder"},{"t":"text","v":"。要 "},{"t":"code","v":"compareAndSet"},{"t":"text","v":"、要随时读准确当前值，还用 "},{"t":"code","v":"AtomicLong"},{"t":"text","v":"。"}]}],"parentId":"thread-说说Atomic类"},{"id":"thread-说说Atomic类-ABA-用哪个类","module":"thread","title":"ABA 用哪个类","level":"extra","summary":"AtomicStampedReference：值和 stamp（版本）一起 CAS。…","blocks":[{"type":"p","inlines":[{"t":"code","v":"AtomicStampedReference"},{"t":"text","v":"：值和 stamp（版本）一起 CAS。"},{"t":"code","v":"AtomicMarkableReference"},{"t":"text","v":" 只多一个 boolean mark，信息量更少。"}]}],"parentId":"thread-说说Atomic类"},{"id":"thread-说说ReadWriteLock","module":"thread","title":"说说ReadWriteLock","level":"core","summary":"ReadWriteLock 是读写锁接口：读锁共享、写锁独占。多个线程可以同时持有读…","blocks":[{"type":"p","inlines":[{"t":"code","v":"ReadWriteLock"},{"t":"text","v":" 是读写锁接口：读锁共享、写锁独占。多个线程可以同时持有读锁；一旦有人拿写锁，其它读、写都进不来。适合读多写少：缓存、配置、黑白名单。"}]},{"type":"p","inlines":[{"t":"text","v":"标准实现是 "},{"t":"code","v":"ReentrantReadWriteLock"},{"t":"text","v":"。内部有 "},{"t":"code","v":"ReadLock"},{"t":"text","v":"、"},{"t":"code","v":"WriteLock"},{"t":"text","v":" 两把锁，共用同一个继承 AQS 的 "},{"t":"code","v":"Sync"},{"t":"text","v":"。"},{"t":"code","v":"state"},{"t":"text","v":" 被拆成两段用：高位记读锁持有数，低位记写锁重入数（具体位数实现细节面试提一句即可）。读是共享获取，写是独占获取。"}]},{"type":"p","inlines":[{"t":"text","v":"特性可以背："}]},{"type":"li","inlines":[{"t":"text","v":"可重入：同一线程可以再次拿已经持有的读锁或写锁"}]},{"type":"li","inlines":[{"t":"text","v":"锁降级：持有写锁时可以再拿读锁，然后释放写锁，变成只持读——能看到自己写的数据再给别人读。升级（读→写）容易死锁，一般不支持直接升级"}]},{"type":"li","inlines":[{"t":"text","v":"公平/非公平：构造可传，默认非公平，吞吐更好"}]},{"type":"p","inlines":[{"t":"text","v":"读写互斥关系：读-读并行；读-写、写-写互斥。写的时候别人不能读，保证读到的不是改到一半的数据。"}]},{"type":"p","inlines":[{"t":"text","v":"注意：读多写少才有优势；写很频繁时读写锁切换开销大，未必比一把 "},{"t":"code","v":"ReentrantLock"},{"t":"text","v":" 强。读锁期间不能假定数据永远不变——只是「当前没人写」。"}]}]},{"id":"thread-说说ReadWriteLock-和-synchronized--ReentrantLock-怎么选","module":"thread","title":"和 synchronized / ReentrantLock 怎么选","level":"extra","summary":"只要互斥、读写比例差不多：普通互斥锁更简单。读远多于写、读路径要并行：再上读写锁。A…","blocks":[{"type":"p","inlines":[{"t":"text","v":"只要互斥、读写比例差不多：普通互斥锁更简单。读远多于写、读路径要并行：再上读写锁。API 一样要 "},{"t":"code","v":"try/finally"},{"t":"text","v":" 里 unlock。"}]}],"parentId":"thread-说说ReadWriteLock"},{"id":"thread-说说ReadWriteLock-锁降级怎么用","module":"thread","title":"锁降级怎么用","level":"extra","summary":"典型：写锁改完数据 → 获取读锁 → 释放写锁 → 在读锁下用数据 → 释放读锁。中…","blocks":[{"type":"p","inlines":[{"t":"text","v":"典型：写锁改完数据 → 获取读锁 → 释放写锁 → 在读锁下用数据 → 释放读锁。中间一直有锁，别的写进不来，自己读的是刚写完的。"}]}],"parentId":"thread-说说ReadWriteLock"},{"id":"thread-说说ReadWriteLock-StampedLock-是什么","module":"thread","title":"StampedLock 是什么","level":"extra","summary":"JDK 8 的另一种读写思路，多了乐观读：读的时候不加锁，读完校验 stamp，变了…","blocks":[{"type":"p","inlines":[{"t":"text","v":"JDK 8 的另一种读写思路，多了乐观读：读的时候不加锁，读完校验 stamp，变了再走悲观读。比 "},{"t":"code","v":"ReentrantReadWriteLock"},{"t":"text","v":" 更猛，也更容易用错，面试知道「乐观读、不可重入」即可。"}]}],"parentId":"thread-说说ReadWriteLock"},{"id":"thread-说说Semaphore","module":"thread","title":"说说Semaphore","level":"core","summary":"Semaphore 是信号量，用来控制同时访问某资源的线程数。构造时传入许可数量；a…","blocks":[{"type":"p","inlines":[{"t":"code","v":"Semaphore"},{"t":"text","v":" 是信号量，用来控制同时访问某资源的线程数。构造时传入许可数量；"},{"t":"code","v":"acquire"},{"t":"text","v":" 拿许可（没有就阻塞），"},{"t":"code","v":"release"},{"t":"text","v":" 还许可。许可数相当于「还有几个坑位」。"}]},{"type":"p","inlines":[{"t":"text","v":"底层是 AQS 共享模式："},{"t":"code","v":"state"},{"t":"text","v":" 表示剩余许可。"},{"t":"code","v":"acquire"},{"t":"text","v":" 成功就把 "},{"t":"code","v":"state"},{"t":"text","v":" 减掉；减不动就进队列 park。"},{"t":"code","v":"release"},{"t":"text","v":" 加回许可并唤醒等待者。也可以公平、非公平，默认非公平。"}]},{"type":"p","inlines":[{"t":"text","v":"常见场景："}]},{"type":"li","inlines":[{"t":"text","v":"限流：接口最多 N 个线程同时进"}]},{"type":"li","inlines":[{"t":"text","v":"资源池：连接、许可名额固定，用完归还"}]},{"type":"li","inlines":[{"t":"text","v":"限制同时在线人数、同时下载数"}]},{"type":"p","inlines":[{"t":"text","v":"写法注意：只有成功 acquire 之后才在 finally 里 release。若 acquire 抛了中断异常还没拿到许可，finally 里再 release，等于多放了一个许可，池子被放大。正确写法是 acquire 成功后再进业务 try/finally。"}]},{"type":"code","text":"semaphore.acquire();\ntry {\n    // 业务\n} finally {\n    semaphore.release();\n}"},{"type":"p","inlines":[{"t":"code","v":"tryAcquire"},{"t":"text","v":" 可以非阻塞或带超时试拿，适合不想干等的限流。"}]}]},{"id":"thread-说说Semaphore-和锁有什么区别","module":"thread","title":"和锁有什么区别","level":"extra","summary":"锁（互斥）通常许可是 1，同一时刻一个线程。信号量许可可以是 N，同一时刻最多 N …","blocks":[{"type":"p","inlines":[{"t":"text","v":"锁（互斥）通常许可是 1，同一时刻一个线程。信号量许可可以是 N，同一时刻最多 N 个。锁强调临界区互斥；信号量强调名额、限流。"}]}],"parentId":"thread-说说Semaphore"},{"id":"thread-说说Semaphore-CountDownLatch-能当信号量用吗","module":"thread","title":"CountDownLatch 能当信号量用吗","level":"extra","summary":"不能等价。CountDownLatch 是一次性计数开门；Semaphore 许可可…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不能等价。CountDownLatch 是一次性计数开门；Semaphore 许可可反复 acquire/release，是可循环的名额控制。"}]}],"parentId":"thread-说说Semaphore"},{"id":"thread-说说CountDownLatch","module":"thread","title":"说说CountDownLatch","level":"core","summary":"CountDownLatch 是一次性倒计数门栓：构造时给定计数 N，一个或多个线程…","blocks":[{"type":"p","inlines":[{"t":"code","v":"CountDownLatch"},{"t":"text","v":" 是一次性倒计数门栓：构造时给定计数 N，一个或多个线程 "},{"t":"code","v":"await"},{"t":"text","v":" 卡住；别的线程每完成一件事就 "},{"t":"code","v":"countDown"},{"t":"text","v":" 减一，减到 0 时，所有 await 的线程被放行。"}]},{"type":"p","inlines":[{"t":"text","v":"底层 AQS 共享："},{"t":"code","v":"state"},{"t":"text","v":" 就是剩余计数。"},{"t":"code","v":"countDown"},{"t":"text","v":" 把 state 减一，到 0 时唤醒所有等待者。"},{"t":"code","v":"await"},{"t":"text","v":" 发现 state 不为 0 就 park。"}]},{"type":"p","inlines":[{"t":"text","v":"典型用途："}]},{"type":"li","inlines":[{"t":"text","v":"主线程等所有子任务做完再汇总（比如并行查多个服务，齐了再组装结果）"}]},{"type":"li","inlines":[{"t":"text","v":"多个线程等同一个启动信号：计数设 1，准备工作完成后 countDown，大家一起跑"}]},{"type":"li","inlines":[{"t":"text","v":"资源初始化：初始化线程 countDown，业务线程 await"}]},{"type":"p","inlines":[{"t":"text","v":"特点：和 CyclicBarrier 比，它是一次性的，计数归零后不能重置，要再用就 new 一个。角色也不对等：往往是「一个等多个」或「多个等一个信号」，不是「一组人互相等齐」。"}]},{"type":"code","text":"CountDownLatch latch = new CountDownLatch(3);\n// 三个工人任务里最后 latch.countDown();\nlatch.await(); // 主线程等三人完成"}]},{"id":"thread-说说CountDownLatch-和-CyclicBarrier-怎么选","module":"thread","title":"和 CyclicBarrier 怎么选","level":"extra","summary":"主线程等 N 个子任务结束、或一次性开门：用 CountDownLatch。一组线程…","blocks":[{"type":"p","inlines":[{"t":"text","v":"主线程等 N 个子任务结束、或一次性开门：用 CountDownLatch。一组线程互相等到齐、还可能多轮：用 CyclicBarrier。Latch 不能 reset；Barrier 可以循环，还能带 barrierAction。"}]}],"parentId":"thread-说说CountDownLatch"},{"id":"thread-说说CountDownLatch-countDown-多调了会怎样","module":"thread","title":"countDown 多调了会怎样","level":"extra","summary":"减到 0 之后再 countDown，计数不会变负到影响已放行的逻辑（实现上到 0 …","blocks":[{"type":"p","inlines":[{"t":"text","v":"减到 0 之后再 countDown，计数不会变负到影响已放行的逻辑（实现上到 0 就不再减有意义的等待），但说明用法错了。少调则 await 一直等，可能死等，生产要配超时 "},{"t":"code","v":"await(timeout, unit)"},{"t":"text","v":"。"}]}],"parentId":"thread-说说CountDownLatch"},{"id":"thread-说说CountDownLatch-能中断吗","module":"thread","title":"能中断吗","level":"extra","summary":"await 响应中断，会抛 InterruptedException。需要可取消的等…","blocks":[{"type":"p","inlines":[{"t":"code","v":"await"},{"t":"text","v":" 响应中断，会抛 "},{"t":"code","v":"InterruptedException"},{"t":"text","v":"。需要可取消的等待时记得处理中断。"}]}],"parentId":"thread-说说CountDownLatch"},{"id":"thread-说说CyclicBarrier","module":"thread","title":"说说CyclicBarrier","level":"core","summary":"CyclicBarrier 叫回环栅栏：让一组线程互相等待，都到达屏障点之后，再一起…","blocks":[{"type":"p","inlines":[{"t":"code","v":"CyclicBarrier"},{"t":"text","v":" 叫回环栅栏：让一组线程互相等待，都到达屏障点之后，再一起往下跑。构造传入参与线程数 N，每个线程跑到同步点调 "},{"t":"code","v":"await"},{"t":"text","v":"，第 N 个到达时栅栏打开，所有人继续；还可以选择带一个 "},{"t":"code","v":"barrierAction"},{"t":"text","v":"，由最后一个到达的线程先执行这段再放行。"}]},{"type":"p","inlines":[{"t":"text","v":"和 CountDownLatch 最大区别：可重用。一轮结束后计数恢复，下一轮还能再 await。适合「某串行步骤拆成 N 路并行，齐了再进入下一阶段」，多轮迭代也行。"}]},{"type":"p","inlines":[{"t":"text","v":"底层不是直接用 AQS 那套 "},{"t":"code","v":"state"},{"t":"text","v":" 独占/共享那么简单，内部用锁 + Condition 计数（实现细节面试提「可循环的屏障」即可）。"},{"t":"code","v":"await"},{"t":"text","v":" 可响应中断；"},{"t":"code","v":"reset"},{"t":"text","v":" 能打破当前等待并重置屏障（等着的线程会收到 "},{"t":"code","v":"BrokenBarrierException"},{"t":"text","v":"）。"}]},{"type":"code","text":"CyclicBarrier barrier = new CyclicBarrier(3, () -> {\n    // 三人都到齐后执行一次\n});\n// 每个工作线程末尾：\nbarrier.await();"},{"type":"p","inlines":[{"t":"text","v":"场景：多线程分片计算，每轮算完对齐再合并；游戏里多人加载齐了再开局。"}]}]},{"id":"thread-说说CyclicBarrier-和-CountDownLatch-对比怎么背","module":"thread","title":"和 CountDownLatch 对比怎么背","level":"extra","summary":"CountDownLatch：常一个等多个，或等启动信号；一次性，归零作废要 new…","blocks":[{"type":"p","inlines":[{"t":"text","v":"CountDownLatch：常一个等多个，或等启动信号；一次性，归零作废要 new；没有到齐回调。"}]},{"type":"p","inlines":[{"t":"text","v":"CyclicBarrier：多个线程彼此等齐；可循环；到齐后自动下一轮；可带 barrierAction。"}]}],"parentId":"thread-说说CyclicBarrier"},{"id":"thread-说说CyclicBarrier-有线程中断或超时会怎样","module":"thread","title":"有线程中断或超时会怎样","level":"extra","summary":"屏障可能进入 broken 状态，其它还在 await 的线程会抛 BrokenBa…","blocks":[{"type":"p","inlines":[{"t":"text","v":"屏障可能进入 broken 状态，其它还在 await 的线程会抛 "},{"t":"code","v":"BrokenBarrierException"},{"t":"text","v":"。超时用 "},{"t":"code","v":"await(timeout, unit)"},{"t":"text","v":"，超时同样可能弄坏本轮屏障，需要业务决定是否 "},{"t":"code","v":"reset"},{"t":"text","v":" 重来。"}]}],"parentId":"thread-说说CyclicBarrier"},{"id":"thread-说说CyclicBarrier-线程数对不上会怎样","module":"thread","title":"线程数对不上会怎样","level":"extra","summary":"参与方必须和构造时的 parties 一致。少一个永远等不齐；多出来的要另说。线程池…","blocks":[{"type":"p","inlines":[{"t":"text","v":"参与方必须和构造时的 parties 一致。少一个永远等不齐；多出来的要另说。线程池里用时注意别和池大小搞混。"}]}],"parentId":"thread-说说CyclicBarrier"},{"id":"thread-说说线程池","module":"thread","title":"说说线程池","level":"core","summary":"线程池用池化思想管理线程：任务来了复用已有线程，而不是每次 new Thread。好…","blocks":[{"type":"p","inlines":[{"t":"text","v":"线程池用池化思想管理线程：任务来了复用已有线程，而不是每次 "},{"t":"code","v":"new Thread"},{"t":"text","v":"。好处是降低创建/销毁开销、控制并发度、提高响应，还能统一监控、扩展（比如 "},{"t":"code","v":"beforeExecute"},{"t":"text","v":"）。"}]},{"type":"p","inlines":[{"t":"text","v":"Java 里核心实现是 "},{"t":"code","v":"ThreadPoolExecutor"},{"t":"text","v":"。构造关键参数："}]},{"type":"li","inlines":[{"t":"text","v":"corePoolSize：核心线程数。池子一开始可以没有线程，有任务才创建；核心线程默认常驻（也可用 "},{"t":"code","v":"allowCoreThreadTimeOut"},{"t":"text","v":" 让核心也超时收）。"}]},{"type":"li","inlines":[{"t":"text","v":"maximumPoolSize：最大线程数。核心满了、队列也满了，若当前线程数还小于这个值，就再创建非核心线程救急。"}]},{"type":"li","inlines":[{"t":"text","v":"keepAliveTime + unit：非核心空闲超过该时间就回收。若 core == max，没有「非核心」，这个超时基本用不上（除非允许核心超时）。"}]},{"type":"li","inlines":[{"t":"text","v":"workQueue：任务队列，核心满了以后任务先堆这里。"}]},{"type":"li","inlines":[{"t":"text","v":"threadFactory：怎么 new 线程（命名、优先级、是否守护线程）。"}]},{"type":"li","inlines":[{"t":"text","v":"handler：线程数到 max 且队列也满时的拒绝策略。"}]},{"type":"p","inlines":[{"t":"text","v":"执行走向可以背：任务提交 → 线程数小于 core 就建核心线程 → 否则进队列 → 队列满且线程数还小于 max 就建非核心 → 还不行就走拒绝策略。"}]},{"type":"p","inlines":[{"t":"text","v":"四种内置拒绝策略："}]},{"type":"li","inlines":[{"t":"text","v":"AbortPolicy（默认）：抛 "},{"t":"code","v":"RejectedExecutionException"}]},{"type":"li","inlines":[{"t":"text","v":"CallerRunsPolicy：让提交任务的线程自己跑，起到降速反馈"}]},{"type":"li","inlines":[{"t":"text","v":"DiscardOldestPolicy：丢掉队列里最老的，再试一次提交"}]},{"type":"li","inlines":[{"t":"text","v":"DiscardPolicy：默默丢弃新任务，不抛异常"}]},{"type":"p","inlines":[{"t":"text","v":"也可以自己实现 "},{"t":"code","v":"RejectedExecutionHandler"},{"t":"text","v":"。生产一般直接 "},{"t":"code","v":"new ThreadPoolExecutor(...)"},{"t":"text","v":"，把队列界住、拒绝策略想清楚，不要无脑 "},{"t":"code","v":"Executors"},{"t":"text","v":" 工厂方法。"}]}]},{"id":"thread-说说线程池-核心线程和最大线程什么关系","module":"thread","title":"核心线程和最大线程什么关系","level":"extra","summary":"先到 core：优先保证有这么多工人。再往上：任务先排队；队满了才扩到 max。所以…","blocks":[{"type":"p","inlines":[{"t":"text","v":"先到 core：优先保证有这么多工人。再往上：任务先排队；队满了才扩到 max。所以「队列选有界还是无界」会直接改变会不会创建到 max 线程。"}]}],"parentId":"thread-说说线程池"},{"id":"thread-说说线程池-队列怎么选","module":"thread","title":"队列怎么选","level":"extra","summary":"有界 ArrayBlockingQueue：能触发扩容到 max 和拒绝策略，好控资…","blocks":[{"type":"p","inlines":[{"t":"text","v":"有界 "},{"t":"code","v":"ArrayBlockingQueue"},{"t":"text","v":"：能触发扩容到 max 和拒绝策略，好控资源。无界 "},{"t":"code","v":"LinkedBlockingQueue"},{"t":"text","v":"：核心满后任务一直进队，可能永远扩不到 max，却可能把内存撑爆。"},{"t":"code","v":"SynchronousQueue"},{"t":"text","v":" 不存任务，来一个尽量交接给线程，适合「弹性加线程」模型（如 Cached）。"}]}],"parentId":"thread-说说线程池"},{"id":"thread-说说线程池-execute-和-submit-有什么区别","module":"thread","title":"execute 和 submit 有什么区别","level":"extra","summary":"execute 只跑 Runnable，异常往外抛到线程的未捕获处理器。submit…","blocks":[{"type":"p","inlines":[{"t":"code","v":"execute"},{"t":"text","v":" 只跑 "},{"t":"code","v":"Runnable"},{"t":"text","v":"，异常往外抛到线程的未捕获处理器。"},{"t":"code","v":"submit"},{"t":"text","v":" 返回 "},{"t":"code","v":"Future"},{"t":"text","v":"，异常包在 "},{"t":"code","v":"ExecutionException"},{"t":"text","v":" 里，"},{"t":"code","v":"get"},{"t":"text","v":" 时才看到。要结果、要统一处理异常，用 submit。"}]}],"parentId":"thread-说说线程池"},{"id":"thread-为什么不建议用Executors创建线程池","module":"thread","title":"为什么不建议用Executors创建线程池","level":"core","summary":"Executors 几个静态工厂看起来省事，但默认队列、线程数策略容易在高负载下 O…","blocks":[{"type":"p","inlines":[{"t":"code","v":"Executors"},{"t":"text","v":" 几个静态工厂看起来省事，但默认队列、线程数策略容易在高负载下 OOM 或把机器打满，阿里巴巴 Java 开发手册也明确建议自己 "},{"t":"code","v":"new ThreadPoolExecutor"},{"t":"text","v":"，把参数写死、边界写清。"}]},{"type":"p","inlines":[{"t":"text","v":"具体风险："}]},{"type":"li","inlines":[{"t":"code","v":"newFixedThreadPool"},{"t":"text","v":" / "},{"t":"code","v":"newSingleThreadExecutor"},{"t":"text","v":"：队列是无界 "},{"t":"code","v":"LinkedBlockingQueue"},{"t":"text","v":"。核心线程忙不过来时任务无限堆进队列，堆内存可能被任务对象撑爆。"}]},{"type":"li","inlines":[{"t":"code","v":"newCachedThreadPool"},{"t":"text","v":"：core 为 0，"},{"t":"code","v":"maximumPoolSize"},{"t":"text","v":" 是 "},{"t":"code","v":"Integer.MAX_VALUE"},{"t":"text","v":"，队列是 "},{"t":"code","v":"SynchronousQueue"},{"t":"text","v":"。任务来得比对得上时疯狂建线程，线程过多一样 OOM 或把 CPU 打崩。"}]},{"type":"li","inlines":[{"t":"code","v":"newScheduledThreadPool"},{"t":"text","v":"：最大线程同样可达 "},{"t":"code","v":"Integer.MAX_VALUE"},{"t":"text","v":"，延迟任务堆积或调度异常时也有资源风险。"}]},{"type":"p","inlines":[{"t":"text","v":"推荐做法：业务估算 QPS、任务耗时、是否 IO 密集，明确 core、max、有界队列容量、拒绝策略和线程名；需要监控就暴露队列长度、活跃线程数。框架里（Tomcat、各种中间件）也是自己建池，而不是 "},{"t":"code","v":"Executors.newXxx"},{"t":"text","v":"。"}]}]},{"id":"thread-为什么不建议用Executors创建线程池-那-Executors-还能不能用","module":"thread","title":"那 Executors 还能不能用","level":"extra","summary":"演示、单测、抛掷型脚本可以。上线服务、未知流量入口不要用。即便用，也要清楚它内部到底…","blocks":[{"type":"p","inlines":[{"t":"text","v":"演示、单测、抛掷型脚本可以。上线服务、未知流量入口不要用。即便用，也要清楚它内部到底是什么队列、多大 max。"}]}],"parentId":"thread-为什么不建议用Executors创建线程池"},{"id":"thread-为什么不建议用Executors创建线程池-有界队列满了怎么办","module":"thread","title":"有界队列满了怎么办","level":"extra","summary":"靠拒绝策略：抛异常让上游重试、CallerRuns 反压、丢弃并打日志告警，或自定义…","blocks":[{"type":"p","inlines":[{"t":"text","v":"靠拒绝策略：抛异常让上游重试、CallerRuns 反压、丢弃并打日志告警，或自定义落到消息队列。关键是「满了有行为」，而不是静默把内存吃光。"}]}],"parentId":"thread-为什么不建议用Executors创建线程池"},{"id":"thread-为什么不建议用Executors创建线程池-Fixed-和-Cached-怎么记","module":"thread","title":"Fixed 和 Cached 怎么记","level":"extra","summary":"Fixed：线程数固定，队列无限 → 怕积压 OOM。Cached：线程近乎无限，队…","blocks":[{"type":"p","inlines":[{"t":"text","v":"Fixed：线程数固定，队列无限 → 怕积压 OOM。Cached：线程近乎无限，队列不存 → 怕线程爆炸。两者都把「限流」这件事推没了。"}]}],"parentId":"thread-为什么不建议用Executors创建线程池"},{"id":"thread-说说线程池有哪几种状态","module":"thread","title":"说说线程池有哪几种状态","level":"core","summary":"ThreadPoolExecutor 用一个 volatile int ctl 打包…","blocks":[{"type":"p","inlines":[{"t":"code","v":"ThreadPoolExecutor"},{"t":"text","v":" 用一个 "},{"t":"code","v":"volatile int ctl"},{"t":"text","v":" 打包两样东西：高 3 位是运行状态，低 29 位是工人线程数。状态一共五种（有的资料写成六种，是把过渡说岔了，背下面五个即可）。"}]},{"type":"li","inlines":[{"t":"text","v":"RUNNING：初始状态。能接新任务，也能处理队列里的任务。"}]},{"type":"li","inlines":[{"t":"text","v":"SHUTDOWN：调用 "},{"t":"code","v":"shutdown()"},{"t":"text","v":" 进入。不再接新任务，但会把队列里剩下的任务跑完。"}]},{"type":"li","inlines":[{"t":"text","v":"STOP：调用 "},{"t":"code","v":"shutdownNow()"},{"t":"text","v":" 进入（从 RUNNING 或 SHUTDOWN 都能进）。不接新任务，尝试中断正在执行的任务，队列里没跑的也不再处理（返回未执行列表）。"}]},{"type":"li","inlines":[{"t":"text","v":"TIDYING：线程数为 0，且（SHUTDOWN 下队列也空，或已经是 STOP）时进入。会调一次 "},{"t":"code","v":"terminated()"},{"t":"text","v":" 钩子，默认空实现，留给子类做收尾。"}]},{"type":"li","inlines":[{"t":"text","v":"TERMINATED："},{"t":"code","v":"terminated()"},{"t":"text","v":" 跑完后进入。线程池彻底结束。"}]},{"type":"p","inlines":[{"t":"text","v":"状态转换可以背："}]},{"type":"li","inlines":[{"t":"text","v":"RUNNING → SHUTDOWN："},{"t":"code","v":"shutdown()"},{"t":"text","v":"（对象被 GC 时老版本 finalize 也可能间接触发，现在别依赖这个）"}]},{"type":"li","inlines":[{"t":"text","v":"RUNNING 或 SHUTDOWN → STOP："},{"t":"code","v":"shutdownNow()"}]},{"type":"li","inlines":[{"t":"text","v":"SHUTDOWN → TIDYING：队列空且线程数为 0"}]},{"type":"li","inlines":[{"t":"text","v":"STOP → TIDYING：线程数为 0（队列里可能还有未执行任务，但已不处理）"}]},{"type":"li","inlines":[{"t":"text","v":"TIDYING → TERMINATED："},{"t":"code","v":"terminated()"},{"t":"text","v":" 结束"}]},{"type":"p","inlines":[{"t":"text","v":"优雅停机常用：先 "},{"t":"code","v":"shutdown()"},{"t":"text","v":"，"},{"t":"code","v":"awaitTermination"},{"t":"text","v":" 等一段时间，还不停再 "},{"t":"code","v":"shutdownNow()"},{"t":"text","v":"，并处理中断。"}]}]},{"id":"thread-说说线程池有哪几种状态-shutdown-和-shutdownNow-怎么选","module":"thread","title":"shutdown 和 shutdownNow 怎么选","level":"extra","summary":"还能接受把队列里任务做完：shutdown。必须立刻停下、任务可取消：shutdow…","blocks":[{"type":"p","inlines":[{"t":"text","v":"还能接受把队列里任务做完："},{"t":"code","v":"shutdown"},{"t":"text","v":"。必须立刻停下、任务可取消："},{"t":"code","v":"shutdownNow"},{"t":"text","v":"，并确认任务能响应中断。很多业务是「先 shutdown 再限时 await，超时再 shutdownNow」。"}]}],"parentId":"thread-说说线程池有哪几种状态"},{"id":"thread-说说线程池有哪几种状态-为什么要用-ctl-把状态和线程数编在一起","module":"thread","title":"为什么要用 ctl 把状态和线程数编在一起","level":"extra","summary":"要在并发下原子地同时判断「还能不能加线程 / 处在什么生命周期」。一个整数上 CAS…","blocks":[{"type":"p","inlines":[{"t":"text","v":"要在并发下原子地同时判断「还能不能加线程 / 处在什么生命周期」。一个整数上 CAS，避免状态和计数两个字段对不上。"}]}],"parentId":"thread-说说线程池有哪几种状态"},{"id":"thread-说说线程池有哪几种状态-isTerminated-什么时候为-true","module":"thread","title":"isTerminated 什么时候为 true","level":"extra","summary":"只有到 TERMINATED 才是。SHUTDOWN 后队列还在跑时，isShutd…","blocks":[{"type":"p","inlines":[{"t":"text","v":"只有到 TERMINATED 才是。SHUTDOWN 后队列还在跑时，"},{"t":"code","v":"isShutdown"},{"t":"text","v":" 为 true，但 "},{"t":"code","v":"isTerminated"},{"t":"text","v":" 仍是 false。"}]}],"parentId":"thread-说说线程池有哪几种状态"}]
